INSERT INTO "public"."TermsAndConditions" ("id", "name", "html_content", "created_at", "created_by_user_uuid", "deleted") VALUES
	('43e8168c-629c-4248-8041-0bed8b248df1', 'testing', '<p>asdfgh</p>', '2026-06-23 13:34:04.46188+00', NULL, true),
	('2a02b08a-769b-44fa-8a36-9e4006e5eaf5', 'Conditions Générales (En Français)', '<h2>Conditions générales</h2><ol><li><p><strong>Paiement :</strong> Un dépôt de 50 % est exigé au moment de la réservation. Le solde restant doit être payé au plus tard 7 jours avant la date de début de l’événement.</p></li><li><p><strong>Annulation :</strong> Toute annulation effectuée 30 jours ou plus avant l’événement donne droit à un remboursement complet, moins des frais de traitement de 250 $. Toute annulation effectuée moins de 30 jours avant l’événement entraîne la perte du dépôt.</p></li><li><p><strong>Livraison et installation :</strong> Bleacher Rentals assurera la livraison et l’installation de l’équipement à l’endroit convenu. Le client doit s’assurer que le site est accessible et que le sol est de niveau.</p></li><li><p><strong>Responsabilité :</strong> Le client est responsable de tout dommage causé à l’équipement pendant la période de location, à l’exception de l’usure normale.</p></li><li><p><strong>Assurance :</strong> Le client doit fournir une preuve d’assurance responsabilité civile générale d’un montant minimal de 1 000 000 $, désignant Bleacher Rentals comme assuré additionnel.</p></li></ol><p></p>', '2026-08-27 15:50:14.247228+00', NULL, false),
	('805f9267-38ab-4442-84b9-7c9ba3f5f36e', 'Standard Agreement', '<h2>Standard Terms &amp; Conditions</h2><p>1. <strong>Payment: </strong>Unless otherwise agreed in writing, a 50% deposit is required upon booking. The remaining balance is due 7 days before the event start date. Overdue payments are subject to 2% interest per month. </p><p></p><p>2. <strong>Cancellation:</strong> Cancellations made 30+ days before the event receive a full refund minus a $250 processing fee. Cancellations within 30 days forfeit the deposit.</p><p></p><p>3. <strong>Delivery &amp; Setup:</strong> Bleacher Rentals will deliver and set up equipment at the agreed-upon location. The client must ensure the site is accessible and level. A delivery window of 1-3 days before the event and pickup window of 1-3 days after the event is standard, unless otherwise agreed, before signing.</p><p></p><p>4. <strong>Liability:</strong> The client is responsible for any damage to equipment during the rental period beyond normal wear and tear. Clients are NOT authorized to move the bleachers. </p>', '2026-06-22 20:34:51.987793+00', NULL, false);
