	('3e517248-66d8-4837-bb2b-fa8f4d24a5ae', '53978eda-8051-46df-8531-766314593c20', 'fae8f510-96d3-4437-b184-45be5c4b7007', '@Chelsea, It is a 50% deposit like normal, but I''m not exactly sure how to change that.', false, '2026-08-31 14:19:14.825+00', NULL, NULL),
