INSERT INTO "public"."RoadmapFeatures" ("id", "quarter_id", "title", "description", "status", "sort_order", "created_at", "completed_at", "deleted_at") VALUES
	('60f66b67-2e78-4f8f-9b2e-ee04c11c3d40', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Driver App - Offline First', '<p></p>', 'completed', 0, '2026-04-29 17:59:17.159+00', '2026-04-29 17:59:17.455239+00', NULL),
	('1099b45c-d0ab-42fc-85ab-a816951cd0bc', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Driver Trip Flow', '<ol><li><p>Get''s new upcoming trips.</p></li><li><p>marks the trips as accepted</p></li><li><p>todays trips come around</p></li><li><p>starts the first trip</p></li><li><p>drives to the pick up location</p></li><li><p>completes pre trip inspection</p></li><li><p>drives to drop off</p></li><li><p>completed post trip inspection</p></li><li><p>maybe in the near future mark as paid.</p></li></ol><p></p>', 'completed', 0, '2026-04-29 17:59:52.511+00', '2026-04-29 18:00:33.209285+00', NULL),
	('3666c5f7-5f34-4b89-9cbd-9764600dec25', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Driver Onboarding \ Profile', '<p><strong>High Level Overview</strong></p><p>The drivers should be required to upload their required documentation through the app before they''re able to start receiving trips.</p><p>&nbsp;</p><ul><li><p>Name, email, photo, phone number address, license photo, medical card if USA, COI take photo of Certificate of Insurance.</p></li><li><p>Vehicle info, year make model VIN</p></li><li><p>Do they have space to store bleachers? If so how many?</p></li></ul><p></p>', 'completed', 0, '2026-04-29 18:02:44.96+00', '2026-04-29 18:02:45.194142+00', NULL),
	('81b5c1fd-3f25-4cb7-845b-e371c97ab646', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Push Notifications', '<p></p>', 'completed', 0, '2026-04-29 18:03:21.028+00', '2026-04-29 18:03:21.878391+00', NULL),
	('ccde131b-7633-44b8-bbc0-3c8eaa6efa0b', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Driver Blue Book', '<ul><li><p>Should just be a list of resources – links for everything important for the driver.</p></li><li><p>Make this maintainable in a “Drivers Blue Book” page in <a target="_blank" rel="noopener noreferrer nofollow" href="http://BleacherRentals.app">BleacherRentals.app</a> (add &amp; remove)</p></li></ul><p></p>', 'completed', 0, '2026-04-29 18:04:10.713+00', '2026-04-29 18:04:11.137928+00', NULL),
	('f69047b2-a3e9-450c-a276-4607b38b6662', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Work Trackers Generate Bill of Lading', '<p>This coincides with the Bleacher Documentation thing that Michelle told me about. Inspections should be linked to the bleachers like their documentation</p>', 'completed', 0, '2026-04-29 18:04:48.979+00', '2026-04-29 18:04:51.167482+00', NULL),
	('d5b6ec8f-a9b1-4202-982e-8aba0a1815e9', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Better Dashboard Filtering', '<ul><li><p>Save Last filtered settings</p></li><li><p>Only Admins can filter by account manager? (don''t do this yet)</p></li></ul><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>We already have the summer/winter/all button for seasons then we could add an option to select "For who?" This will be a dependencies.</p><p>&nbsp;</p><p>&nbsp;</p><p>We''re going to turn the summer/winter/all button into a "nestible" filter feature</p><p>SEASON &gt; ACCOUNT MANAGER(single) &gt; ROWS ( 10/15/all)</p><p>So the row option will always be visible. the account manager drop down will only be visible if we have a season selected.</p><p>&nbsp;</p><p>&nbsp;</p><p>ALSO TEAM PAGE</p><p>Group by account type in team page. First admins, then account managers, then drivers.</p><p>&nbsp;</p><p>Hide by default the inactive users.</p><p>&nbsp;</p><p>&nbsp;</p><p>Only admins:</p><ul><li><p>can make other users inactive</p></li><li><p>can make other users admins</p></li></ul><p></p>', 'completed', 0, '2026-04-29 18:05:16.912+00', '2026-04-29 18:05:17.081171+00', NULL),
	('6b661392-2771-4a12-b52e-51e243154601', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Swap Bleacher Button', '<p></p>', 'completed', 0, '2026-04-29 18:05:55.028+00', '2026-04-29 18:05:55.259881+00', NULL),
	('6039ec56-f800-4fe0-b913-853816fc8136', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Scorecard', '<p></p>', 'completed', 0, '2026-04-29 18:06:09.862+00', '2026-04-29 18:06:10.028913+00', NULL),
	('3d60d2ab-5a1f-4f56-b38d-ecbc965079b2', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Track Driver Pay', '<p>Basically do this in the software: <a target="_blank" rel="noopener noreferrer nofollow" href="https://docs.google.com/spreadsheets/d/1wbSRYG2eK0Z_W-IQtstLsy71KVAGKJSNfXbYOdJrpt4/edit?gid=227497168#gid=227497168">https://docs.google.com/spreadsheets/d/1wbSRYG2eK0Z_W-IQtstLsy71KVAGKJSNfXbYOdJrpt4/edit?gid=227497168#gid=227497168</a></p><p>&nbsp;</p><ol><li><p>Work Tracker Complete (Ready to be sent)</p></li><li><p>Work tracker sent to driver</p></li><li><p>Driver has Accepted the Work tracker</p></li><li><p>Driver has completed the Work</p></li></ol><p>&nbsp;</p><p>create type worktracker_status as enum (</p><p> ''draft'', -- created by account manager, not visible to driver</p><p> ''released'', -- visible to driver, waiting for accept</p><p> ''accepted'', -- driver has accepted, not started yet</p><p> ''in_progress'', -- driver pressed "Start trip"</p><p> ''completed'', -- post-trip done</p><p> ''cancelled'' -- optional</p><p>);</p><p>&nbsp;</p><p>Maybe add one more that says "Paid" drivers been paid. Completed triggers ready to be paid.</p><p>&nbsp;</p>', 'completed', 0, '2026-04-29 18:06:57.114+00', '2026-04-29 18:06:57.368732+00', NULL),
	('956477e3-e695-4f41-ade6-41dacdb9d0e1', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Remove Address from Event Bar', '<p>Should we remove the address from the event bar on the dashboard and wrap the text of the title</p>', 'completed', 0, '2026-04-29 18:07:27.696+00', '2026-04-29 18:07:27.864677+00', NULL),
	('ecfb1958-eb97-4a9a-8a6b-6c52b5bad6a2', '1557df40-3f57-4e2d-b76c-16f53c1876cb', 'Overlapping Events', '<p>UI Design how overlapping events should be displayed so you can have multiple events quoted for the same bleacher.</p>', 'completed', 0, '2026-04-29 18:07:43.597+00', '2026-04-29 18:07:43.74767+00', NULL),
	('03e1a9ca-f418-4f24-8616-7e3e867ae63e', '8b9af269-926f-445f-b09f-097c23f287db', 'Inspection Pipeline / Asset Tracking', '<p>Worktrackers should show that cascading alert badge so we can see which work tracker has trips with issues.</p><p>&nbsp;</p><p>Also on the Assets page should be able to see which bleachers have issues.</p><p>&nbsp;</p><p>Add a new page called Damage Log - that shows all damages</p><p>this page should allow you to mark logs as REPORTED, SCHEDULED, IN-PROGRESS, RESOLVED.</p><p>&nbsp;</p><p>Email automation to Michelle.</p><p>Instead of hard-coding michelles email. Add some role to the teams page called "Maintenance Coordinator" make it known that all this does is send email notifications when damage is reported.</p><p>&nbsp;</p><p>On dashboard if a bleacher has an REPORTED, SCHEDULED, or IN-PROGRESS, problem, but a icon on the cell that links to the inspection details.</p><p>&nbsp;</p><p>Also add this icon with the same link to the work tracker modal so the account manager can quickly access any issues before assigning the bleacher to the driver.</p><p>&nbsp;</p>', 'completed', 0, '2026-04-29 18:16:34.085+00', '2026-04-29 18:16:34.387039+00', NULL),
	('ae71b346-5186-48e0-9a93-abf3d0303d44', '8b9af269-926f-445f-b09f-097c23f287db', 'Driver Availability', '<p>Drivers should be able to set their availability in the app. This will most likely be simply the ability to mark entire days as "Unavailable" maybe add an option for indefinite recurring.</p><p>&nbsp;</p><p>Steal some UI/UX from google calendar probs.</p><p>&nbsp;</p><p>Questions:</p><ul><li><p>Do we need to set recurring availability dates?</p></li><li><p>What should it look like on the web app?</p><ul><li><p>Maybe just show an alert for drivers who are unavailable during selected date? This could be in the driver selection drop down on the work tracker or it could be on the work tracker if it''s saved on the dashboard.</p></li></ul></li><li><p>Should the account manager be able to request unavailable dates to be available?</p></li><li><p>Should the driver see a special indicator on the trips if it''s marked on an unavailable date?</p></li><li><p>Do we need a calendar view in the web app to see each drivers vailability?</p></li><li><p></p></li></ul><p>There should be a calender view in web</p>', 'completed', 0, '2026-04-29 18:17:18.175+00', '2026-04-29 18:17:18.564821+00', NULL),
	('3d186eaa-80e6-4bfc-b771-0868bbc7a56c', '8b9af269-926f-445f-b09f-097c23f287db', 'Alerts', '<p>Create a system to make adding and editing alerts scalable.</p><p>Alerts to be created</p><ul><li><p>Event Requirements are not met. (this compares number of seats, rows, bleachers, etc. with the bleachers that have been selected.)</p></li><li><p>Overlapping Booked Events. If two booked events are overlapping this should throw an error.</p></li><li><p>Bleachers change location without a work tracker.</p></li><li><p>This weeks Work Trackers have not been released yet. Maybe another one for upcoming work trackers have not been accepted by the driver yet.</p></li></ul><p></p>', 'completed', 0, '2026-05-04 17:32:18.452+00', '2026-06-25 13:06:48.965516+00', NULL),
	('e86a0a1c-a4d0-4cd2-8f30-67ee4d347d4c', '8b9af269-926f-445f-b09f-097c23f287db', 'Get Rid of Seasons / Sub-rental Support', '<p>no summer/winter home base. and there will only be one account manager assigned. Get rid of summer winter toggle.</p><p>Internal subrental support. A mechanism for account managers to book events on bleachers they don''t own.</p><p>external subrental support. Sometimes a customer buys a couple bleachers and we still rent them out.</p><p>We won''t know the schedule of the venues that have bought bleachers so we would need to call to ask for permission to rent them.</p>', 'completed', 0, '2026-05-04 17:33:01.453+00', '2026-06-25 13:06:56.223514+00', NULL),
	('99776dbb-8ab2-4d98-bc73-d808d106bc5e', '8b9af269-926f-445f-b09f-097c23f287db', 'Send Quotes - Beta', '<p>Sometimes send as PDF via email if you don''t want them to sign. (Attache PDF? Yes/no)</p><p>&nbsp;</p><p>Send them a link to a Quote portal where the user can see the live data and sign. Should be sent from the account managers email wkthout leaving <a target="_blank" rel="noopener noreferrer nofollow" href="http://bleacherrentals.app">bleacherrentals.app</a>.</p><p>&nbsp;</p><p>33% Credit Card Payments</p><p>33% Wire ACH</p><p>34% Physical Check</p><p>1% Cash</p><p>&nbsp;</p><p>Having Quotes Be able to get signed automatically. Use an inventory list instead of "Bleacher 37" we''d assign "15 Row Bleacher"</p><p>&nbsp;</p><p>Be cool if we could automate the price on the quote. Rural, city, corperate. How many days. Option to update price manually. ﻿<a target="_blank" rel="noopener noreferrer nofollow" class="link" href="https://docs.google.com/spreadsheets/d/11RD_N0ZlLIVjqU8ojCYk9d4SyUsjoxq21u8zGkR2RrU/edit?gid=1458565150#gid=1458565150">Google SheetGoogle Drive File</a>﻿</p><p>&nbsp;</p><p>Stripe Integration</p><p></p><p></p><p>Not going to be used this quarter but will be used in Q3</p>', 'completed', 0, '2026-05-04 17:34:03.536+00', '2026-06-25 13:07:09.076323+00', NULL),
	('f676c232-b8f0-4b7f-85cf-0c35bf191aa8', '8b9af269-926f-445f-b09f-097c23f287db', 'Medical Card Removal', '<p>Can we make the Medical Card on the driver profiles non mandatory? Some drivers don''t have these yet and they are not able to accept trips or do pre and post trip inspections.</p>', 'draft', 0, '2026-05-21 17:08:34.033+00', NULL, NULL),
	('a02e9ed6-0f75-469e-85c8-8762607cd890', '8b9af269-926f-445f-b09f-097c23f287db', 'Inability to send invite to driver', '<p>I keep getting an error message when trying to send an invite to a driver. It says email already exists and unable to send an invitation. I am trying to get him set up to do a run. <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:bburrel6@gmail.com">bburrel6@gmail.com</a></p>', 'completed', 0, '2026-06-17 17:09:05.071+00', '2026-06-22 13:33:01.606883+00', NULL),
	('85ea5827-4cb2-4c1b-a7da-72a6c611ae5e', '8b9af269-926f-445f-b09f-097c23f287db', 'Driver ScoreCard', '<p>Could we add another number 6 on here as a bonus rock.&nbsp;&nbsp;</p><p>&nbsp;</p><p>6.&nbsp; Add a drivers scorecard,&nbsp; &nbsp;We would track how many miles each driver hauled bleachers&nbsp;throughout the year,&nbsp; &nbsp;at the end of the year we can issue a bonus on this based on $.02/ mile,&nbsp; minus any damages, fines or extra unexpected&nbsp;costs.&nbsp; &nbsp; &nbsp; &nbsp;The bonus could be based on company&nbsp;total repair costs,&nbsp; if we stay under $100,000 then all drivers split this divided on the miles they drove.&nbsp; Must drive 20,000 miles to qualify.&nbsp; &nbsp;&nbsp;</p><p>&nbsp;</p><p>Can we track how many miles each driver hauls and have a driver''s leaderboard?</p><p>&nbsp;</p><p>Ultimately, we would create a drivers database and internal load board essentially,&nbsp; not sure how or if this will work,&nbsp; but it''s been in my idea bank for over 5 years.</p><p>&nbsp;</p><p><strong>Questions</strong></p><p>Does this include deadhead?</p>', 'completed', 0, '2026-05-04 17:31:22.787+00', '2026-06-15 16:59:00.232178+00', NULL),
	('4f57b8cd-0145-4667-b7af-7f97effe5350', '8b9af269-926f-445f-b09f-097c23f287db', 'Permissions', '<p>How do you bring on a new account manager safely? Denver just brought on todd and it was a bit worrying knowing he had full access right off the bat. We''re also prone to hackers if someone really wanted to delete all our data (we would be able to restore it) but they would be able to get authorization by sending to our back end with an authenticated token. We can create rules in our back end to not allow users who have a status of deactivated to make any changes for example.</p><p>&nbsp;</p><p><strong>Add a View Only Mode for Lead Drivers</strong></p><p>&nbsp;</p><p>Event Logger? Cyber Security</p><p>&nbsp;</p><p>&nbsp;</p><p>Drivers need to be able to view only the dashboard. "View your account managers Bleachers" should be an option</p><p>&nbsp;</p><p>Potential Permissions Ideas:</p><ul><li><p>New role called: "View Only" where a user can access the web app and see all the data, but is not able to make create, update, or delete any data. they can only read.</p></li><li><p>Create a system to easily implement new permissions policies. This system should include cybersecurity practices to enforce these permissions on the server that checks to make sure each action is allowed to be made to the database.</p></li><li><p>Ensure admins are the only ones who are able to make other admins and deactivate accounts. Everyone else can create new accounts.</p></li><li><p>Account managers can change their own assignments (drivers and bleachers) but cannot change other peoples assignments.</p></li><li><p>Account Managers cannot make changes to events owned by other account managers.</p></li><li><p>Account managers cannot create events for other account managers either.</p></li><li><p>Account managers cannot edit work trackers made by other drivers. Maybe can only edit work trackers for drivers that are assigned to them?</p></li><li><p>Only admins can make changes to scorecard targets.</p></li><li><p>only admins can make changes to zones</p></li></ul><p></p>', 'completed', 0, '2026-05-04 17:33:35.82+00', '2026-06-25 13:07:04.245319+00', NULL),
	('90e4e2a3-a387-4321-9b26-29b46175fdc1', 'e8bba0cb-40bb-4f80-87fe-67782dfbe730', 'Phase 2: Optimize and improve the quote/invoice feature in software', '<ul><li><p>All account managers a quoting though the software and no longer using goodshuffle for quoting purposes</p></li></ul><ul><li><p>Quotes and events have a working database similar to goodshuffle so we can view past and future quote/invoices for each client and event location.</p></li><li><p>All quote/invoice related inquiries and bug fixes are addressed and solved</p></li><li><p>Auto sales tax amounts working</p></li><li><p>Sales by state for tax reporting ? (Maybe this is a future rock)</p></li></ul><p></p>', 'in_progress', 0, '2026-07-21 13:06:37.892+00', NULL, NULL),
	('c42cf160-f426-4eb0-a150-9665ba679edf', 'e8bba0cb-40bb-4f80-87fe-67782dfbe730', 'Phase 1: Optimize the driver''s app, work tracker, and damage reporting workflow.', '<ul><li><p>All app related inquiries are addressed and bugs fixed</p></li><li><p>The trip creation process is simplified, functional and followed by all</p></li><li><p>All Feature requests and bugs are addressed in trip/work tracker creations</p></li><li><p>Work trackers sync with QuickBooks, and bug/features are addressed.</p></li><li><p>All damage reporting is working and optimized creating a database of repairs on each asset</p></li></ul><p></p>', 'in_progress', 0, '2026-07-21 13:04:22.993+00', NULL, NULL),
	('cf0187d0-d9e5-4c62-8696-f3220c435b4d', 'e8bba0cb-40bb-4f80-87fe-67782dfbe730', 'Phase 3: Internal communication Beta version created.', '<ul><li><p>Team members can send messages and notification to each other about events from the dashboard</p></li><li><p>Team members can send internal messages about quotes and clients inside each quote, similar to goodshuffles messaging process.&nbsp;</p></li></ul><p></p>', 'completed', 0, '2026-07-21 13:10:50.856+00', '2026-08-25 14:01:06.999122+00', NULL),
	('be1098cc-2453-4659-9315-f26aabbe64e8', '10db4d8b-c6ea-4115-8e19-1bc4e9130d07', 'AI Route Optimization', '<p></p>', 'draft', 0, '2026-09-08 14:05:46.874+00', NULL, NULL),
	('09bc5df4-4ded-4a6a-85d4-f54076b4452b', '10db4d8b-c6ea-4115-8e19-1bc4e9130d07', 'Finance And Data Harnessing Reporting', '<p>Filtering and Database stuff all the clients</p>', 'draft', 0, '2026-09-08 14:04:43.81+00', NULL, NULL),
	('bc4b881f-34e9-4728-90ee-025a7dba6f54', '10db4d8b-c6ea-4115-8e19-1bc4e9130d07', 'Task Management software', '<p></p>', 'draft', 0, '2026-09-08 14:05:07.242+00', NULL, NULL);
