--

  "Thanks for your payment" — sent to the CLIENT after a payment is received
  (trigger: payment_made_client).

  Same clean, table-based, inline-styled structure as contract-signed.html
  (Gmail/Outlook safe). Uses only tokens defined in variables.ts:
    {{firstName}} {{customerName}} {{quoteLink}} {{quoteNumber}}
    {{eventName}} {{eventStartDate}} {{total}} {{amountPaid}} {{amountDue}}
    {{accountManager}} Bleacher Rentals
-->
<div style="background-color: #dbe5ea; padding: 0; margin: 0">
  <!-- Header: brand + View Invoice button -->
  <table
    width="100%"
    border="0"
    cellspacing="0"
    cellpadding="0"
    style="border-spacing: 0; width: 100%; background-color: #ffffff; border-bottom: 1px solid #d7dbe0"
  >
    <tbody>
      <tr>
        <td style="padding: 16px; text-align: center">
          <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; max-width: 600px; margin: 0 auto">
            <tbody>
              <tr>
                <td style="text-align: left; vertical-align: middle; font-family: Helvetica, Arial, sans-serif; font-size: 20px; font-weight: bold; color: #3e484d">
                  Bleacher Rentals
                </td>
                <td style="text-align: right; vertical-align: middle">
                  <a
                    href="{{quoteLink}}"
                    target="_blank"
                    style="display: inline-block; background-color: #405daa; color: #ffffff; font-family: Helvetica, Arial, sans-serif; border-radius: 4px; font-weight: bold; font-size: 14px; padding: 8px 16px; text-decoration: none"
                  >
                    View Invoice
                  </a>
                </td>
              </tr>
            </tbody>
          </table>
        </td>
      </tr>
    </tbody>
  </table>

  <!-- Success icon + title -->
  <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; width: 100%; background-color: #ffffff">
    <tbody>
      <tr>
        <td style="padding: 32px 16px 8px; text-align: center">
          <table align="center" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; margin: 0 auto 12px">
            <tbody>
              <tr>
                <td style="background-color: #2e9e5b; border-radius: 40px; width: 56px; height: 56px; text-align: center; vertical-align: middle; font-family: Helvetica, Arial, sans-serif; font-size: 30px; color: #ffffff; line-height: 56px">
                  ✓
                </td>
              </tr>
            </tbody>
          </table>
          <h1 style="margin: 0; padding: 0; font-family: Helvetica, Arial, sans-serif; font-weight: bold; color: #3e484d; font-size: 30px; line-height: 40px">
            Thanks for your payment!
          </h1>
        </td>
      </tr>
    </tbody>
  </table>

  <!-- Body copy -->
  <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; width: 100%; background-color: #ffffff">
    <tbody>
      <tr>
        <td style="padding: 16px; text-align: center">
          <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; max-width: 600px; margin: 0 auto">
            <tbody>
              <tr>
                <td style="padding: 0 16px; color: #616161; font-family: Helvetica, Arial, sans-serif; font-size: 16px; line-height: 23px; text-align: left">
                  <div>
                    Hi {{firstName}}, we''ve received your payment of
                    <strong>{{amountPaid}}</strong> toward <strong>{{eventName}}</strong>
                    (invoice #{{quoteNumber}}). Thank you!
                  </div>
                  <div><br /></div>
                  <div>
                    A summary of your invoice is below. If you have any questions about your
                    balance or your booking, just reply to this email.
                  </div>

                  <br /><br />
                  <div>Sincerely,<br /><br />{{accountManager}}<br />Bleacher Rentals</div>
                </td>
              </tr>
            </tbody>
          </table>
        </td>
      </tr>
    </tbody>
  </table>

  <!-- Payment summary -->
  <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; width: 100%; background-color: #ffffff">
    <tbody>
      <tr>
        <td style="padding: 16px; text-align: center">
          <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0; max-width: 600px; margin: 0 auto">
            <tbody>
              <tr>
                <td width="50%" style="vertical-align: top; padding: 0 16px; text-align: left; font-family: Helvetica, Arial, sans-serif">
                  <h6 style="margin: 20px 0 8px; padding: 0; font-weight: bold; color: #3e484d; font-size: 13px; line-height: 20px">Event</h6>
                  <p style="color: #616161; font-size: 14px; line-height: 20px; margin: 0 0 16px">
                    {{eventName}}<br />
                    {{eventStartDate}}
                  </p>
                  <h6 style="margin: 20px 0 8px; padding: 0; font-weight: bold; color: #3e484d; font-size: 13px; line-height: 20px">Contact</h6>
                  <p style="color: #616161; font-size: 14px; line-height: 20px; margin: 0 0 16px">{{customerName}}</p>
                </td>
                <td width="50%" style="vertical-align: top; padding: 0 16px; text-align: left; font-family: Helvetica, Arial, sans-serif">
                  <table width="100%" border="0" cellspacing="0" cellpadding="0" style="border-spacing: 0">
                    <tbody>
                      <tr>
                        <td style="background-color: #f4f6f8; border-radius: 4px; padding: 0 16px 16px; text-align: left">
                          <h6 style="margin: 20px 0 8px; padding: 0; font-weight: bold; color: #3e484d; font-size: 13px; line-height: 20px">Invoice Details</h6>
                          <p style="color: #616161; font-size: 14px; line-height: 20px; margin: 0 0 16px">
                            Invoice Number: {{quoteNumber}}<br /><br />
                            <b>
                              <span style="color: #2e9e5b">Payment Received: {{amountPaid}}</span><br />
                              Balance Remaining: {{amountDue}}<br />
