	('07514f0f-b7f4-4063-9712-05a4627a25ce', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Setup 2nd Interview with Max', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:48:03.154+00', '2026-05-05 12:48:03.296691+00', NULL),
	('40139fbd-c37b-470b-8be5-f39f299eae41', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Send Rejection Emails', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:48:49.47+00', '2026-05-05 12:48:49.670947+00', NULL),
	('f3856f0f-db6a-4b6d-8e49-e5b229ed5b6b', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Organize Roadmap in BR App', '<p>I ended up recreating my workflow from Clickup in the Bleacher rentals roadmap. Clickup was trying to ask for money to have Custom Statuses so I just moved everything to our own software.<br><br>Now we should be able to simply move backlog items into the sprints with ease and we can communicate on certain features as required with the instant messaging.</p><p></p><p>I still need to go through all the backlog items though</p><p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-04-30 19:35:24.801+00', '2026-05-05 12:49:15.546259+00', NULL),
	('529061ff-9b35-4709-8374-7ccddc27a472', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, '2nd interview with Max and Krista', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-07 18:45:54.756+00', '2026-05-07 18:45:55.035283+00', NULL),
	('840859fe-6bb5-4766-943f-9987d3b20dbb', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Alert - Overlapping Booked Events', '<p>If two booked events are overlapping this should throw an alert.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:52:25.986+00', '2026-05-07 19:00:56.297559+00', NULL),
	('08fbbff7-b8d1-4048-8b20-265d3155757b', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Create a system to make adding and editing alerts scalable.', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:45:11.022+00', '2026-05-07 19:01:06.063856+00', NULL),
	('fac8721f-5440-40e6-8fe1-f6e8eb88b24e', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Alert - Event Requirements are not met', '<p>this compares number of seats, rows, bleachers, etc. with the bleachers that have been selected.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:47:21.069+00', '2026-05-07 19:01:15.922975+00', NULL),
