	('eacebd90-4d95-422d-ab24-a7d20a111306', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Help Devin With Driver App Blockage', '<p>He was talking to michelle saying the app was just showing a white screen even after a few restarts. He''s on iphone. When I hopped on a call with him one more close then open seemed to do the trick. Not happy that I don''t know what was going on here...</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-08 17:41:34.768+00', '2026-05-08 17:41:35.174736+00', NULL),
	('82a17f1f-abcf-472e-af32-7324c441b9fa', '42fedbbd-2d36-41c0-ad6b-bbe4b8a4d3ed', NULL, 'Get Contract to Max', '<p>Waiting for Krista and Kaitlyn to come up with a good payment setup for Max because he''s overseas and asked for 1k USD monthly</p><p></p><p>Not sure what went down in there meeting but Krista should have the contract ready this weekend and then will jump on a call next week to set up max in accounting.</p>', 'in_progress', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-07 18:47:04.288+00', NULL, NULL),
	('f9d21998-53c0-4ad2-b6c8-b6e7445fd3d0', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Review Max''s PR - First Permission Implementation', '<p>Prettier check - failed then fixed. added a prettier ci check so max knows in the future to follow the prettier config.</p><p></p><p>added the supabase run checks to the pr-ci</p>', 'in_progress', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-20 15:07:57.295+00', NULL, NULL),
	('33f1a76b-c9f6-4231-9577-41625e1bee9e', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Changes requested on PR 253', '<p>account managers cannot view the teams page. the teams page should be accessible by account managers. heres an explanation: <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/ae6a03ae5d7e473ebdcedf3b4276fffd"><u>https://www.loom.com/share/ae6a03ae5d7e473ebdcedf3b4276fffd</u></a></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-20 21:23:39.376+00', '2026-05-21 13:11:55.740997+00', NULL),
