	('ab3ef727-0526-4ad5-bb6b-e797673a2999', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Alert - This weeks Work Trackers have not been released yet', '<p>Maybe another one for upcoming work trackers have not been accepted by the driver yet.</p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 12:53:25.553+00', NULL, NULL),
	('db05d0da-732d-4a21-8de2-12a532a59820', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Remove Bonus Column in Driver Scorecard', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 13:26:19.331+00', '2026-06-08 16:24:46.329006+00', NULL),
	('80f72fd8-911a-4752-8e81-665cfd8ad1c8', NULL, NULL, 'Too Many Inspection Submissions per Trip!', '<p>Good Morning. I am seeing in the software a couple of drivers have multiple pre/post trip submissions for the same bleacher on the same day. Like 6 of them LOL any idea why that would be? the software shouldn''t let them do more than just 1 pre trip and 1 post trip per asset correct?</p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-04 14:29:33.15+00', '2026-06-16 13:50:39.782154+00', NULL),
	('fd42730a-8f5e-4b52-94f7-d6a60d505545', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Change Bleachers Row in RBAC Matrix Account Managers badge', '<p>Account Managers badge should be read only not custom badge.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-25 13:28:48.853+00', '2026-05-25 22:01:33.88634+00', NULL),
	('9d0b0a01-ccf8-4ce5-afe8-715db172e86d', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Developer Permissions', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-26 13:13:03.019+00', '2026-05-27 11:19:39.720978+00', NULL),
	('16958745-16d5-452c-9151-f44051656fcd', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'Create Send Quotes Feature Plan', '<p>Create a little plan that put''s together a Minimum Viable Product for the Send Quotes feature.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-27 18:50:22.048+00', '2026-05-28 19:45:51.67887+00', NULL),
	('5b3127f4-17c5-4452-924b-8f0b424c0307', NULL, NULL, 'Account Managers can assign a "Lead Driver"', '<p><strong>In Mobile App</strong></p><p>The lead driver should be able to <em>impersonate</em> another driver in the driver app within same zone. Should hide pay info and the lead driver should not be able to CRUD data at all.</p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 13:38:59.003+00', '2026-06-16 13:53:31.724166+00', NULL),
	('d67e7be9-dbf4-44cd-85ff-faeb1ef637ae', '499b152d-7cde-4d20-8ea6-a7091de4e6d2', NULL, 'Cant Click on Repairs in Repairs Page', '<p>You should probably be able to click on the repair here to acceess the details like the files stuff.</p><p></p><p>Make sure the words are clickable in the event span. clicking on the repair in the repairs page should open the maintenance event in the dashboard.</p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-04 16:42:59.435+00', '2026-07-29 17:55:49.560455+00', NULL),
	('7a4229a1-c018-4031-b61a-15d6091dad6c', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Complete Google Classroom stuff', '<p>you can find the invite in your email. Try clicking this link soon because it might expire or something</p><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-11 16:35:40.243+00', '2026-05-15 17:14:17.209916+00', NULL),
	('f29f7e7b-c1b6-42d5-a7c1-1df9d899cc8c', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Zone Manager', '<p>admins have full crud, everyone else = no access. enforce this policy and update the RBAC Matrix to accurately reflect this.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-25 13:59:00.058+00', '2026-05-25 22:02:05.564646+00', NULL),
	('3b446820-2016-412f-8cdb-a0d9c8734995', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'come up with a QA System', '<p>I need to create a structure for reviewing max''s code and ensuring that bugs are not deployed to prod without slowing down efficiency in the development cycle</p><p></p><ol><li><p>I prompted claud opus 4.6 like this for max''s big PR:<br></p><p>could you check out PR 253 from my /Users/joshredgrift/Documents/Bleacher_Rentals/br_next/bleacher_rentals repository and also check out PR 22 from /Users/joshredgrift/Documents/Bleacher_Rentals/br_powersync and generate me a list of things that I should test. take your time to be thorough with your audit, and then give me a good list of things that might have been affected by the code changes.</p></li></ol><p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 17:28:35.619+00', NULL, NULL),
	('3d84e944-6c76-4694-91eb-1d7723c0e0f1', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Remove No Roles Error for Developers', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 14:14:40.517+00', '2026-05-12 14:14:41.010335+00', NULL),
	('becafd5d-b154-4452-b492-5708704ec4ca', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Add Github Permissions', '<p>so max can''t accidentially deploy to prod or to the supabase environments</p><p></p><p>This seems to be okay. I added a permission, and pull requests are now required for develop, staging, and main branches. I''m pretty sure the only person who can accept them is the owner of the repo. </p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 15:28:22.413+00', '2026-05-12 20:55:53.396727+00', NULL),
	('6bbe1d6b-fa64-412f-be6a-43b57633e3cd', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Don''t forget about sprint 3 branch changes with the alert code not pushed to prod yet', '<p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 14:22:51.928+00', NULL, NULL),
	('7ddf7303-9ee2-4c3b-a35d-9502580b2c53', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Research Supabase RLS', '<p>Row Level Security. you can create RLS "Policies" that allow different permissions on the data base written in postgresql in a migration file.</p><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 14:20:40.663+00', '2026-05-13 18:30:35.762575+00', NULL),
	('e9f6fb26-4bd7-41f4-b519-e5aa7380c7c5', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Add Developer to "Additional Roles" column in the teams page', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 14:15:40.201+00', '2026-05-12 15:26:51.592675+00', NULL),
	('35434b5d-1810-4249-b92f-b1f2fe1e250a', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'bug report - cannot select other bleachers at location.', '<p>So basically, Justin had a problem because he couldn''t find any bleachers that were at the address that he was picking up from. He grabbed a bleacher that his work tracker was not assigned to. The reason why the bleacher was not assigned to him was because the address that they were picking up from differed slightly from the address that the bleacher was supposed to be at.</p><p>The feature that I need to make is the ability to link addresses between events and work trackers. If an account manager is creating a work tracker, instead of typing a new address, they can select the address that the system thinks this bleacher is at. It will link it so that if they want to update this address, it will update all the addresses as well. It should probably throw an alert saying that if you change the address here, it''s going to change it in all these other places. </p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 19:39:45.617+00', NULL, NULL),
	('2de9b3d4-8d76-4aaf-b090-7acc1e15804e', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Create Shared Prettier Config', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 15:07:04.285+00', '2026-05-12 19:59:53.010368+00', NULL),
	('3de9eb64-b530-4ff7-bce8-0e62997ebc5a', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Manual Testing All Permissions', '<p>see if you can find any bugs! and fix.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-26 13:13:40.949+00', '2026-05-27 11:19:46.904024+00', NULL),
	('088d5643-6a06-4144-b142-db4c144d5b3a', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'what is SyncStreamConnectionMethod.HTTP?', '<p>Max required HTTP connection method to work with PowerSync locally, so I need to learn what it is and if we should push this to production or not.</p><p></p><p>It''s an alternative to WebSockets. It has slightly higher payload and slightly longer latency than WebSockets, but it has better compatibility most of the time. Some browsers and Docker setups don''t allow for WebSocket connections, so HTTP is more likely to be usable and probably won''t hurt anything if we push this change to production. </p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 21:08:38.295+00', '2026-05-14 17:19:12.841492+00', NULL),
	('3004f26d-75ef-45ae-b884-58dbc732fce1', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Send Bank Info to Kaitlyn', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-11 18:59:34.513+00', '2026-05-14 18:54:09.1397+00', NULL),
	('f5a89bdb-7898-4f44-a91a-fc03d6c17019', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'developers should redirect to roadmap instantly', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 14:34:39.51+00', '2026-05-14 18:54:26.263056+00', NULL),
	('fdbb8238-4a47-488f-821e-d6aa9a96923f', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Only Developer Bug', '<p>When a user with only a Developer Role assigned. they cannot access the application.</p><p></p><h1><strong>STEP ONE</strong></h1><p>Explore the code base and see if you can figure out a plan on how this change should be implemented and we will discuss to see if you''re on the right track and then we will move forward to actually make the changes to this feature.</p><p></p><p><strong>What Access Do Developers Need to Have In Web App?</strong></p><ul><li><p>Developers should be able to access only the roadmap pages. Developers can CRUD any Roadmap information.</p></li><li><p>Developers Cannot CRUD any other data. They cant see the dashboard or work trackers or anything else other than the Roadmap pages including the backlog.</p></li></ul><p></p><p><strong>Enforce RLS safety so developers can only CRUD Roadmap tables.</strong></p><ul><li><p>Users that are inactive on the Users table (status colum)</p></li><li><p>if they are an admin and/or an account manager then they should be able to CRUD</p></li><li><p>make sure each role is_active = true (if it''s false then the role is not applied to this user)</p></li></ul><p></p><p></p><p></p><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-11 14:16:20.229+00', '2026-05-15 17:14:10.382221+00', NULL),
	('8fcec403-b436-44ad-b5a1-ed87f5fe446d', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'permission Quickbooks Connections', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-25 13:49:19.763+00', '2026-05-25 22:01:43.785404+00', NULL),
	('fac3e445-3cfb-469b-80d5-72d1bd0c05f0', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'heif/heic photo display error', '<p>cannot see photos taken by iphone in web app in the Damage Reports page on <a target="_blank" rel="noopener noreferrer nofollow" href="http://bleacherrentals.app">bleacherrentals.app</a> some photos aren''t displaying properly because they are heic or heif or something. You should convert them to JPG before uploading </p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-19 19:05:01.786+00', '2026-05-27 18:57:58.168831+00', NULL),
	('7fc21cd0-101b-48ca-996f-c361d18f1f8a', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'Create Line Item Modal', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-28 19:50:03.211+00', '2026-06-05 13:15:10.849409+00', NULL),
	('0db8b337-a441-41c5-879c-7722ebc29e78', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Work Tracker Save Time', '<p>Sometimes work trackers take forever to save</p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:49:46.016+00', NULL, NULL),
	('14463fa1-d424-4cc7-bd7f-bc4dd4e1c28c', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'migrate powersync to sync streams', '<p>We needed to migrate from sync rules to sync streams in PowerSync, which is now the recommended way to go based on their documentation. That''s good. All I did here was make changes locally. I want to make sure it works well with Max''s local development setup before pushing to production. If Max has no issues over the next couple of days, then I will try migrating just the PowerSync to production to see if this is working properly. I will make another ticket for pushing PowerSync sync streams to production. </p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-13 18:37:34.511+00', '2026-05-13 18:37:35.039495+00', NULL),
	('cc816265-4908-410f-b9f9-1b1f3db4065f', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Hide deactivated drivers from Work Tracker driver select', '<p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/75ee1e7074ce4f36b3c7eed420fa9f8d">https://www.loom.com/share/75ee1e7074ce4f36b3c7eed420fa9f8d</a></p><p></p><p><strong>Description:</strong><br>When creating or editing a Work Tracker, the driver dropdown currently includes drivers who have been deactivated. Deactivated drivers should not appear as selectable options.</p><p>A driver should be excluded from the dropdown if either of these conditions is true:</p><ol><li><p>The related <code>Users.statusId</code> points to an inactive status.</p></li><li><p>The related driver record has <code>isActive = false</code>.</p></li></ol><p>This issue was noticed in the Work Tracker modal under the driver selection field. The relevant code appears to be in the Work Tracker feature area, likely around:</p><p><code>features/work-tracker/.../WorkTrackerModal</code><br>and/or the <code>SelectDriver</code> component.</p><p><strong>Expected behavior:</strong><br>Only active drivers should appear in the Work Tracker driver select list.</p><p><strong>Actual behavior:</strong><br>Drivers marked as inactive/deactivated are still visible and selectable.</p><p><strong>Acceptance criteria:</strong></p><ul><li><p>Deactivated drivers are hidden from the Work Tracker driver dropdown.</p></li><li><p>Drivers are hidden if either their user status is inactive or their driver record has <code>isActive = false</code>.</p></li><li><p>Existing active drivers still appear as expected.</p></li><li><p>This applies when creating a new Work Tracker and when editing an existing one.</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-12 14:48:22.399+00', '2026-05-13 19:31:41.410305+00', NULL),
	('c0039566-40ae-45f9-8f76-41588d5eac69', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Give Max More Permission Tasks', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-14 13:13:35.358+00', '2026-05-14 15:13:19.870278+00', NULL),
	('28ed8837-ebc2-470d-ab3a-43f5e01a0813', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Developer sync stream rules in powersync.', '<p>I''ve migrated the power sync branch to use sync streams. The branch is called sync-streams.</p><p>Please use this branch to create the developer sync stream rules where developers are unable to access all tables other than those prefixed with the word roadmap.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-13 18:40:25.769+00', '2026-05-15 17:13:19.160817+00', NULL),
	('497da137-dd2a-49da-b137-9e063bf4d5e5', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Manage Inspection Form - change Matrix to no access for AM', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-25 13:52:05.495+00', '2026-05-25 22:01:55.8963+00', NULL),
	('c0569781-c815-448c-826f-c0fa054ee257', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'View Only Role', '<p>Create a new role in the manage team page that allows a user to only have viewing permissions for all of the data but cannot write anything. </p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-14 14:06:51.5+00', '2026-05-19 13:20:47.487278+00', NULL),
	('6e6a3a79-3b9c-4b0f-8f15-a4207ca3549e', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Account Manager Permissions', '<ul><li><p>Account managers can change their own assignments (drivers and bleachers) but cannot change other peoples assignments. <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/8b61fb14aca542bcb9cbe57919c5cb67">Here''s what I mean Click Me to See Loom Video</a></p></li><li><p>Account Managers cannot make changes to events owned by other account managers. <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/bc48cf0c8c434eb3ba1f758988653566">Video Explainer</a></p></li><li><p>Account managers cannot create events for other account managers either.</p></li><li><p>Account managers cannot edit work trackers for drivers that are not assigned to them. <a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/3fc0ba38736a4b598ce49219d82a9444">Video Explainer</a></p></li><li><p>Account managers should have view only access to the assets page and should not be able to make changes to the bleachers. they should not be able to create, delete or update. only read.</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-14 14:36:07.556+00', '2026-05-22 18:02:11.169222+00', NULL),
	('74e2b765-1480-4ab8-8fc1-95a4ee5e8bef', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Sales Scorecard', '<p>Remove redundant row in RBAC Matrix and enforce policy.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-25 14:02:38.972+00', '2026-05-26 12:54:36.760338+00', NULL),
	('fc585a03-8d65-485e-b56b-3ead55ba0b71', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Bleacher_Rentals Pull Request to Develop', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-26 13:14:19.732+00', '2026-05-27 11:19:52.736959+00', NULL),
	('813c4724-b95c-49df-9517-6c147226643c', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Admin Permissions', '<ul><li><p>Only admins can make changes to scorecard targets. (<a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/a2af26ce6b4e4df7a4bc013c74f7ecd2">Video Explainer</a>)</p></li><li><p>Only admins can make changes to Zones, Quickbooks &amp; Inspection (<a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/7e0531082f974e929240a8f17d4eef12">Video Explainer</a>)</p></li><li><p>Admins are the only ones who are able to make other admins. Account Managers can still create new accounts. (<a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/d7f4898e011c4691898298b44f13cea2">Video Inspection</a>)</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-14 16:54:05.431+00', '2026-05-27 11:21:11.72666+00', NULL),
	('282fc521-31a9-4250-91b6-9f67e515089c', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'Figure out Electronic Signature Plan', '<p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-28 19:53:48.556+00', NULL, NULL),
	('79ec0d8a-7d5c-4ea6-bec0-5e39a0447056', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'Create Quotes Files/Attachements Sections', '<p></p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-28 21:03:47.031+00', NULL, NULL),
	('ae519c63-2d7b-4f6d-ade7-e212e2ba437a', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'Create Quotes Logs Section', '<p></p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-28 21:04:23.031+00', NULL, NULL),
	('76ea9387-767a-40fe-8218-4e638143c416', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'Create Maintainable Prices Plan & feature', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-29 19:19:04.311+00', '2026-06-01 19:40:31.840126+00', NULL),
	('51e25d58-541d-43a0-8441-3e1e4d696d09', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'Create Contact Modal', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-28 19:49:37.361+00', '2026-06-01 21:23:11.426173+00', NULL),
	('23572f5f-8277-4f48-9b29-f57905896b43', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'review permissions PR', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-27 19:00:22.865+00', '2026-06-05 13:15:54.748907+00', NULL),
	('76c3ddef-98fd-468b-9469-b42d9dd2f063', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'create price matrix db schema', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-29 18:26:07.515+00', '2026-06-05 13:16:37.535913+00', NULL),
	('6b1784ff-0b1d-4e6c-ac2c-c431c995e242', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Create an Architectural Plan for Permissions', '<p><strong>Goal</strong></p><p>Create a lightweight plan for how permissions should be handled across the Bleacher Rentals web app.</p><p>This does not need to be a formal document. A few clear notes are enough. The goal is to avoid adding random permission checks throughout the app without a consistent pattern.</p><p></p><p><strong>Task</strong></p><p>Write a short architecture plan for how permissions should work.</p><p>Please cover:</p><ul><li><p>How roles should work when a user has multiple roles</p></li><li><p>How Admin, Account Manager, Driver, and Developer permissions should differ</p></li><li><p>How to separate web app access from mobile app access</p></li><li><p>Whether view-only access should be a role, boolean, enum, or something else</p></li><li><p>How frontend permission checks should be structured</p></li><li><p>How permissions should be enforced securely with Supabase/RLS/backend logic</p></li><li><p>Any special handling needed for roadmap, tickets, to-dos, and backlog tables</p></li></ul><p></p><p>Should also probably have some <strong>feature flags</strong> for permissions because if people are using the app or people are already using the app and we add permissions that make them unable to do stuff that they need to do, we should be able to quickly revert the changes while we try to implement a fix and then iterate that way. </p><p></p><p><strong>Notes</strong></p><p>Do not spend too much time polishing this. The plan can just be written notes.</p><p>The important thing is to recommend a clear pattern so future permission work is consistent.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-14 14:12:24.317+00', '2026-05-14 16:46:06.172548+00', NULL),
	('906fa966-ced8-4166-b6e7-5a237be1d705', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Review Max''s Architectural Decisions for Permissions', '<p>He''s not over complicating it for right now. That''s good.<br><br>RLS, for All CRUD operations. Copy Read RLS policies to powersync rules. Similar setup for client side stuff. Going to stick with Role Based Access Control instead of Attribute Based Access Control.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-14 17:26:05.979+00', '2026-05-15 13:58:25.07184+00', NULL),
	('6c6ba0c1-8653-4067-8a57-85bc0040b594', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Debug Sync Rules Syntax', '<p><code>SELECT "Events".* FROM "Events"</code><br><code> JOIN "Users" ON "Events"."created_by_user_uuid" = "Users"."id"</code><br><code> WHERE connection.parameter(''app'') = ''web''</code><br><code> AND "Users"."clerk_user_id" = auth.user_id()</code> </p><p></p><p>This sync rule seemed to work for me!</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-15 13:59:41.349+00', '2026-05-15 13:59:41.79964+00', NULL),
	('ef42a992-c919-4d41-8101-5843f481a1fa', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Adding an address in the quote modal', '<p>Current behavior:<br>When creating a quote in the modal window, an issue occurs while adding an address: it is impossible to select an address from the suggested options list.</p><p></p><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-05-19 17:55:52.009+00', '2026-05-27 15:49:53.204836+00', NULL),
	('a957d569-d0ae-48c7-8075-0ad3bbf5f4e6', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Inspections Are uploading in Duplicates Sometimes', '<p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-19 19:01:56.89+00', NULL, NULL),
	('06dd1277-e313-44c1-bc12-b6c0dec49188', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Inspections should have photos manditory', '<p>Drop off photo (setup if applicable)</p><p>photo on pickup too</p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-19 19:04:20.702+00', NULL, NULL),
	('3e5ed3af-cfc7-4e4a-9363-c0cd4c669228', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'Get Mobile App Running Locally', '<p>on iphone get expo app.<br><br>Then in br_mobile make sure you have supabase running locally and powersync running locally as well. start the app with npm start then you will need to click "s" to change to expo go.<br><br></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-27 13:44:03.178+00', '2026-05-27 18:50:09.356557+00', NULL),
	('70c817ab-7a74-4eb5-8521-a5764a27470d', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Add Prettier PR - CI', '<p>fail PR merge if prettier does not have proper formatting.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-20 16:36:00.122+00', '2026-05-20 16:36:00.420785+00', NULL),
	('c8ae14ee-d00e-4c5a-8e35-94031b6cfd7b', '0d27234a-69d8-447c-8a3c-7b04889acfcb', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'Ensure Deactivated Users Have No Server-Side Permissions', '<p>Ensure that if a user has a status that is marked as inactive, no matter what their other permissions are, they should not have any read, write, update, or delete ability in the database or with Powersync sync rules. </p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-21 10:40:30.763+00', '2026-05-25 12:51:05.59758+00', NULL),
	('a17dd8c0-8981-4517-bbf7-6cc3632d69d5', '0d27234a-69d8-447c-8a3c-7b04889acfcb', NULL, 'Email Automation for Cool Labs to Chealsea', '<p>Automatically forward the email to Chealsea when Cool Labs sends an invoice. </p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-20 19:28:50.466+00', '2026-05-21 12:07:01.059347+00', NULL),
