	('4669e916-b41a-40b5-b10a-9eba5b0eda5a', NULL, NULL, 'Scorecard update', '<p>Scorecard signed quote amount should change every time an event is updated after signing, the current updated date, used for the difference in the new contract, IE, plus or minus depending on the amount changed</p>', 'completed', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-06-11 17:58:27.723+00', '2026-06-16 14:06:56.774316+00', NULL),
	('810ce168-7b3e-4d3c-9265-189b742c29d0', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'The Server Needed to Be Restarted Over the weekend. Figure out Why', '<p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-10 12:08:26.402+00', NULL, NULL),
	('69b5bc7a-5b38-47b3-8f34-71439612be18', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Review with Mike - Internal Messaging', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-06 13:53:41.039+00', '2026-08-12 18:50:14.749402+00', NULL),
	('c7e8c2aa-f3aa-46d6-b059-2d37c6587647', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Review with Mike - Work Tracker Plan', '<p></p>', 'in_progress', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-06 13:54:07.14+00', NULL, NULL),
	('b6d92fe1-2419-451a-a52d-225a4f92bcb0', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'create small document for pricing logic (description)', '<p>bleacher type price = event number of days -&gt; (look up price table)</p><p></p><p>if the event days is one day over the maximum days in the biggest bracket then double. front end don''t allow the user to create price matrix with gaps between days. maybe backend reinforced too.</p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-29 18:29:02.629+00', NULL, '2026-06-05 13:17:01.573+00'),
	('0654c010-4b63-4c3b-bdb0-85fc32a5cffb', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'Soft delete on Events', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-05 13:17:49.939+00', '2026-06-05 13:17:50.309882+00', NULL),
	('2d60f9f8-c957-4103-8021-dbfa341caff2', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'BUG - Account Managers Cannot Edit Existing Work Trackers', '<p>After we pushed these changes to the work trackers the created_by_user_uuid is null on exsiting work trackers so they can''t edit existing ones. create backfill migration<br><br><strong>Can this account manager edit this work tracker?</strong></p><ul><li><p>If you own this bleacher then yes.</p></li><li><p>if you don''t own the driver then doesn''t matter</p></li></ul><p></p><p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-03 17:00:37.809+00', '2026-06-05 13:20:10.586865+00', NULL),
	('35b38453-536f-49c1-a16e-cdb2f99998a1', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', '03e1a9ca-f418-4f24-8616-7e3e867ae63e', 'Damage Reports', '<p><strong>Create branch from Main Include Photo Conversion. Test Offline capabilities by using real device and turning wifi/data off and doing CRUDs and then turning internat back on and check DB</strong></p><ol><li><p>Create new columns in inspection table for enums none minor major, for seating_damage and hauling damage. Create bleacher_uuid FK and stop getting the front end to right to the inspection_uuid.</p><ol><li><p>Be backwards compatible so people with older versions of the application still work. This means don''t reference the inspection_uuid from client anymore but have a trigger that keeps both the inspection_uuid and the bleacher_uuid populated regardles of which one was set.</p></li></ol></li><li><p>New page on mobile app to create damage report.</p></li><li><p>update existing damage report code to set bleacher_uuid instead of inspection.</p></li><li><p>update web app to look at the new enums instead of the old values. Also make sure that the src/features/dashboard/ui/event/worktracker/unavailableOverlay.ts is red if there is at least on major damage and yellow if there is minor or no damage.</p></li><li><p>Make sure photos actually end up in storage lol</p></li></ol><p></p><p></p>', 'in_progress', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-05 13:41:20.194+00', NULL, NULL),
	('5832697b-c376-4c3c-98e1-e4aafc239222', 'c4d83a6e-28fb-4ac3-9146-4892895595a4', NULL, 'Force Update Feature', '<p>Create a new table in db fetch with powersync and have client-side code that checks if theres a newer version available and if we should force the user to update now or suggest them.</p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-05 13:51:51.511+00', NULL, NULL),
	('adb0e36c-d575-4fa2-8c27-a1a7616ca318', NULL, NULL, 'Should we allow events to have bleachers for DIFFERENT lengths of time?', '<p>QB-Laser Quatum wanted to pull out a bleacher from a long-term rental and so we needed to create a new event to have the dashboard refla=ect properly but this doesn;t feel right</p>', 'to_do', 0, true, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-06 14:12:48.063+00', NULL, NULL),
	('c400a87c-3242-41cd-91a6-192df8426060', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Hide this line/bleacher (Dashbaord)', '<p>Just like in Google Sheets, you can right click and say "Hide this line arbitrarily", and then maybe at the top you click on "Show all" or something like that.</p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-09 14:22:47.915+00', NULL, NULL),
	('ed420759-b967-4f06-80b4-02a9b74c60c6', NULL, NULL, 'damage reports are not clicable to change after saving,', '<p>be nice to review and cange damage reports as needed. - mike</p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-06-05 16:22:30.562+00', '2026-06-16 13:55:39.733604+00', NULL),
	('af424890-2ca0-464d-9b2c-e65bd6693c38', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Make sure you can actually take payments', '<p>We can receive payments but we should probably handle via webhook to mark things as paid in the db and be able to track payments over time and to get a receipt emailed to the user.</p>', 'in_progress', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-16 13:38:49.477+00', NULL, '2026-06-17 22:29:16.286+00'),
	('3220c8ab-ffe7-4ea8-ac65-40a1055688a9', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Account Managers should be able to create any work trackers', '<p>just needs the proper account manager to send it. Can you hear me? So, if you are not the right account manager, then it will send the proper account manager an email to send the work tracker notification to the driver. When you click on that email, it should open up the exact work tracker modal that allows you to hit Save and Send and whatever.<br><br>This will be resolved with the lead/junior account manager roles when assigning to zones.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-09 14:07:12.034+00', '2026-06-17 22:30:37.303342+00', NULL),
	('60f4fb00-6c87-450f-9469-922e48944cbe', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', '4f57b8cd-0145-4667-b7af-7f97effe5350', 'able to see multiple zones at same time on dashboard', '<p><strong>Lead Account Manager</strong></p><ul><li><p>can CRUD everything in this zone (Events and WorkTrackers) on all bleachers that are assigned to this zone. ✓</p></li></ul><p><br><strong>Junior Account Manager (Restrictions) -</strong></p><ul><li><p>Cannot Send Work Trackers to Drivers (But can create them)</p></li><li><p>Cannot Edit/Delete anything they didn''t create themselves.</p></li></ul><p></p><p>There should be a "Zone Selector" that allows you to select multiple zones at the same time and see the total bleachers selected for this zone. ✓</p><p></p><p>Phase 1 - Open up the back end on these data types to allow most access and deploy this feature as front-end only. ✓</p><p></p><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-09 13:11:05.906+00', '2026-06-18 20:34:14.895677+00', NULL),
	('e00458b8-6a2d-49a5-b9d1-0e228d10acee', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'Event Logs - record deletes', '<p>When someone deletes a quote, record who and when they deleted the event. (Soft Deletes)</p><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-18 15:59:58.667+00', '2026-06-18 21:38:03.286499+00', NULL),
	('5f0fe77b-25ab-4dec-b4cf-2989e42794db', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Alert Bugs', '<p>Creating an event in the quotes page should save alerts to the DB and they dont.</p><p>saving a work tracker does not resolve bleacher transportation alert.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-18 13:36:34.249+00', '2026-06-23 13:24:11.610939+00', NULL),
	('feeb8541-f40a-4d22-81dd-e67170f16374', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Remove Junior Account Manager restrictions', '<ul><li><p>sending quotes</p></li><li><p>remove request permissions for worktrackers</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-22 16:25:22.483+00', '2026-06-22 17:09:32.446113+00', NULL),
	('bb51072e-b2c2-44ba-92d0-39db230dde58', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Prepare for Pushing to Production', '<p>What needs to be done to push to production?</p><ul><li><p>Migrations?</p></li><li><p>Backfilling data?</p></li><li><p>Are we going to break anything with new schema migrations?</p></li><li><p>What else</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-22 16:26:45.201+00', '2026-06-22 17:35:20.005636+00', NULL),
	('d79116d3-df9d-475f-a805-901176ca4b0f', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', 'e86a0a1c-a4d0-4cd2-8f30-67ee4d347d4c', 'Storage Locations', '<p>separate page for creating storage locations. each one has name and address. will display first 15 chars on the BleacherCell.ts in dashboard. Add Contact number as well. Gate code too. And Notes section.</p><p></p><p>create table public."StorageLocations"<br>name,</p><p>address_uuid</p><p>contact_phone_number</p><p>gate_code</p><p>notes</p><p></p><p></p><p>create a page for ADMINS to maintain this please</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-22 14:28:34.91+00', '2026-06-23 13:46:37.354136+00', NULL),
	('74079e10-8a66-4f7c-bb42-5a9e4b95abf7', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Check Choose File for driver profile', '<p>Does this bug out on iphone and android? can the drivers cancel this action properly?</p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-10 13:53:46.924+00', NULL, NULL),
	('13691246-4466-4aab-bb88-f4bd4d2857e1', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Internal Messaging - Is this rock complete?', '<p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-12 18:50:28.488+00', NULL, NULL),
	('6feed00d-7807-4f20-8649-b4cd5c37806b', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Invert Major/Minor damage values to match mobile', '<p>Sarah made the major and minor damages inverted for trailer and seating. so we''re seeing yellow indicator on the dashboard when we should see red</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-01 17:30:56.289+00', '2026-06-08 14:11:04.745659+00', NULL),
	('f6afb1f0-1d39-4784-a725-45f8e7b73225', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'truncate event name on quotes sent page', '<p>The quotes sent has to much white space to the left of the name, i have to scroll far right to see the totals. make columns smaller</p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-19 19:10:54.914+00', '2026-06-08 15:47:00.650566+00', NULL),
	('ba77fecf-c938-4566-9059-e095c9817c59', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Add Total Distance to Bleacher in Assets', '<p>All time not per year</p><p>select all worktrackers that are assigned to this bleacher and add all distance meters or whatever. just display in KMs. calculate on client. On the edit bleacher sheet in assets page.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-05 13:27:54.63+00', '2026-06-08 16:24:36.863568+00', NULL),
	('ee846c44-fe17-4ea2-8594-8d0c20f48383', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Event Created_at should be overridable', '<p>Just like booked at, allow the created date time to be set to a different date/time</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-08 20:23:58.984+00', '2026-06-12 13:42:57.615528+00', NULL),
