	('947e1193-c1db-4e24-b852-0d8e354b4d70', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Override tax Send quotes feature', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-09 13:26:18.557+00', '2026-06-12 13:43:50.987681+00', NULL),
	('64b029ce-626e-4bce-ba04-dbfa7572e3f5', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', '99776dbb-8ab2-4d98-bc73-d808d106bc5e', 'DUE JUNE 16 - Add Finance Contact', '<p>It''s just adding another contact that the account manager can assign to the event or the quote or the booking, or whatever you want to call it. This contact would be labeled the finance contact who handles the payments and stuff like that.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-09 13:53:32.657+00', '2026-06-16 13:00:27.566147+00', NULL),
	('acba8e39-cf79-431d-93e8-ca2ca1729dc1', NULL, NULL, 'See if you can reproduce - Slow saving times for work trackers', '<p>denver said that when you create an event, or a work tracker it would take like 15 seconds to save.</p>', 'to_do', 0, true, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-06 14:15:46.583+00', NULL, NULL),
