	('79b20e4d-e596-4bd6-92cf-0a2d8c5d3274', NULL, NULL, '"Details" when entering an event', '<p>When entering an event, an error pops up that no bleacher has been chosen. In details, it no longer gives us the option to choose whether it is a 15 row, 10 row, 7 row etc.</p>', 'to_do', 0, true, NULL, 'fae8f510-96d3-4437-b184-45be5c4b7007', '2026-06-23 13:24:50.294+00', NULL, NULL),
