	('b9c4e2a5-4e92-427c-be5e-4c33207f55e4', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Sales Office Clean-up', '<ul><li><p>allow editing a sales office</p></li><li><p>show the QboConnection.display_name instead of uuid</p></li><li><p>use typedExecute for optimistic updates</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-23 13:33:46.26+00', '2026-06-23 15:32:36.165537+00', NULL),
	('4be98413-ea84-461b-a9e1-cfbcc7262cc1', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Default Payment Schedule', '<p>50% due on signing</p><p>remaining 50% due 7 days before the event_start</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-23 13:28:29.007+00', '2026-06-23 16:00:33.212007+00', NULL),
