	('42d5dea9-573a-4cf3-95db-37ee9d9b7ce6', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Update Assets/Bleachers Page', '<ul><li><p>Add a Zone selector drop down to the bleacher sheet.</p></li><li><p>Remove the summer/winter home bases and account managers (4 fields)</p></li><li><p>Make sure the table reflects the Zones instead of the old fields.</p></li></ul><p>It would also be nice if this whole page was converted to use Powersync instead of supabase api for CRUD operations. I feel like this page has poor code quality with lots of duplicated code as well so if it''s not a lot of work to focus on some clean code here that would also be nice but not super important if you think it will be a lot of work and is not worth it.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-23 14:53:21.643+00', '2026-06-23 18:28:42.756461+00', NULL),
	('727480eb-0c90-47d4-9eb4-6c5cb0259b63', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Bug cannot see deactivated Account Managers', '<p>in team page</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-24 17:57:59.72+00', '2026-06-24 20:42:13.453723+00', NULL),
	('5efe1c48-9565-4fcb-a114-04e1139f99a3', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Swap supabase to powersync on assets page', '<p>It would also be nice if this whole page was converted to use Powersync instead of supabase api for CRUD operations. I feel like this page has poor code quality with lots of duplicated code as well so if it''s not a lot of work to focus on some clean code here that would also be nice but not super important if you think it will be a lot of work and is not worth it.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-06-23 18:29:14.766+00', '2026-06-23 20:43:18.549582+00', NULL),
	('4c14ace4-215d-4517-9407-7c313cb41677', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Damage Report created by user uuid default to current user', '<p>please create a migration to autopopulate who created the damage report.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-23 20:35:39.658+00', '2026-06-24 14:54:15.308447+00', NULL),
	('58990d8f-de98-493f-bb58-a516bad15396', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Soft Delete Damage Reports', '<p>Please allow admins to soft-delete damage reports in the webapp.<br><br>Allow them to be recoverable by showing deleted damage reports.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-23 20:34:46.576+00', '2026-06-24 14:54:35.930227+00', NULL),
	('f95f3e9c-4fd8-4f98-a2ee-c4d081912a2d', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Save selected zone to dashboard filter settings so the filter persists after refreshes', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-23 21:00:10.229+00', '2026-06-24 17:17:17.904072+00', NULL),
	('869a8e04-c561-43f3-a585-253a871fe732', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Put the Storage Location beside the pin icon in BleacherCell.ts', '<p>because zone names can get longer, its better to put the storage location beside the pin icon.<br>15 character long</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-24 17:27:16.735+00', '2026-06-25 10:50:38.217224+00', NULL),
	('2cdbe39e-141c-4947-a7da-3a3ace9c91ab', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Contacts and Companies should be a search format', '<p>When editing an event when selecting a contact and a company there might be thousands of contacts and companies later on so it should be easier to search and find the existing contact/company.<br><br>Maybe you should not allow contact/companies with duplicate values on certain fields. Like the email address or the phone number. If there are 5 contacts that all have the exact same email, maybe they should all be one contact. same with companies.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-24 17:44:55.981+00', '2026-06-25 12:50:46.864307+00', NULL),
	('47c496d5-a190-4a49-b0e4-139151f8a003', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Convert Work Trackers to Powersync', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-24 17:48:08.899+00', '2026-06-26 17:26:20.986926+00', NULL),
	('04014553-81ac-4486-bd1c-ab5a10e411ba', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Driver Welcome Screen', '<p>when a driver logs into the Web App display a screen that tells the driver they need to download the app with links to the app stores. I think we have one src/features/userAccess/components/DriverWelcome.tsx here</p><p></p><p>Only when user has Driver Role and no other roles assigned</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-24 17:25:32.768+00', '2026-06-25 08:48:20.221322+00', NULL),
	('fe88d260-0231-4a7b-8743-da0394a1c96f', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Revisit template / override logic on payment schedule', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-24 17:33:27.78+00', '2026-06-29 22:49:59.803671+00', NULL),
