	('acb265b6-07a1-408e-ba7f-68b38f17ca7a', NULL, NULL, 'Link event quote number to trip', '<p>Each trip has a last know adress before and after, if one of those adress is an event... aka not a storage location, then the quote/ invoice number should be auto populating in that box, a pickup event and a drop off invoice number should be shown,</p>', 'to_do', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-06-25 11:30:13.09+00', NULL, NULL),
	('3bf2559a-8438-4057-8cb8-c6b71e7c0ae0', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Storage Locations Page should use Powersync Reactive Query', '<p>add restore button and show deleted as well.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-25 13:28:17.389+00', '2026-06-29 13:57:14.737726+00', NULL),
	('ca3d6316-9dc1-4633-af29-f80db0670bb7', NULL, NULL, 'Maintenance Updates', '<p>Be able to filter damage reports by Zone. </p>', 'to_do', 0, true, NULL, '04d8fe31-ba63-4037-8f89-c6383bdcfade', '2026-06-29 20:37:01.522+00', NULL, NULL),
	('a6b926b6-2c15-4f63-8d4c-2ed9a8ca259f', NULL, NULL, 'Damage reports update', '<p>Damage reports are no longer clickable,  and maintenance logs need to be editable. </p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-06-25 11:15:03.813+00', '2026-07-29 18:09:09.813949+00', NULL),
	('c9a80624-2da5-497b-9959-989db231c059', '438f4c13-7bbf-4dbf-bc85-ee6f86d02bbb', NULL, 'Driver App - Drivers License/Insurance Expiration Dates', '<p>Have a spot to enter DL &amp; Insurance expiry date in the Drivers Profile, and the app would notify the Driver and AM, or Admin when expiring. Or some sort of flag on the driver profile to show that the is expired.</p>', 'completed', 0, true, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '04d8fe31-ba63-4037-8f89-c6383bdcfade', '2026-06-29 20:38:53.238+00', '2026-07-23 20:30:40.887325+00', NULL),
	('49e474c9-6b3a-4d47-9208-68ebc0785cb4', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Recreate Texas Task Trans Damage Report Error', '<p></p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-06 16:11:56.087+00', NULL, NULL),
	('f740289f-d139-4342-9038-f8ed2511c69a', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Issue with production stripe webhook.', '<p>Working in development but not in production.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-10 16:17:23.332+00', '2026-08-12 18:50:36.58369+00', NULL),
	('220c1afe-fd76-42e2-9842-461b550c9577', NULL, NULL, 'Event zone sorting,  make sticky', '<p>Make the event sorting sticky, so that it stays the same the last time each user refreshes or logs in. this should also open the zone that is assigned to the Account manager</p>', 'completed', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-06-25 11:19:20.421+00', '2026-08-24 22:30:24.662217+00', NULL),
	('b36aea39-a30d-49ae-88cf-668496b17e88', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'permissions for who can delete what events', '<ul><li><p>ADMINS CAN DO ANYTHING</p></li><li><p>If event is assigned to another account manager, I cannot reassign to myself</p></li><li><p>If Event has at least one bleacher in a zone that I don''t have access to, then only the event owner can modify/delete. Then can only unassign from bleachers they don''t own but cannot assign to bleachers they don''t own.</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-06-22 14:20:26.886+00', '2026-06-29 21:11:21.796212+00', NULL),
	('f1889d7f-54f1-46b0-98c7-a614c0cdb51a', 'd3056243-c26f-4f7c-ba49-92b608ac8a61', NULL, 'Click on red squiggly line on dashboard', '<p>When you click on a cell and this bealcher has an open damage repot add a icon to the cellEditor modal to view the damage report.<br><br>FYI Figure out why there are no more red squiggly lines on the dashboard.<br><br>Also allow admins to edit the maintenance/repairs on the repairs page.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-05-19 19:34:35.062+00', '2026-06-30 20:02:54.978048+00', NULL),
