	('4b0d34a9-ff03-44e6-854e-02eceb74e9d9', '438f4c13-7bbf-4dbf-bc85-ee6f86d02bbb', NULL, 'Driver App - Fix Bottom Sheet (pop up) for Android', '<p>When a driver opens the app and they have outstanding trips to accept, a popup tells them to accept these trips and apparently android users couldn''t get rid of it.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-07-21 13:28:13.722+00', '2026-07-21 13:29:06.408462+00', NULL),
	('3ea3ea30-edd2-43a0-874d-3d64a799313f', '438f4c13-7bbf-4dbf-bc85-ee6f86d02bbb', NULL, 'Driver App - Fix incorrect trip numbers', '<p>drivers saw "you have 17 trips" and only 5 were displayed. problem was the number was including "draft" work trackers.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-07-21 13:30:58.604+00', '2026-07-21 13:30:58.926631+00', NULL),
