	('e6d72403-c111-46ae-9d9e-5f936ef3f519', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Pull Develop into Feature Branch and Create PR with Develop', '<p>include a list of all tickets that were associated with this PR</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-06 13:17:38.479+00', '2026-08-06 18:03:33.191748+00', NULL),
	('75af49f0-a30a-4ff4-8b7f-17d20a8690b8', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Get Max a new Build for Mobile app', '<p>and see if we''re approved for the apple organization account</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-10 11:30:04.766+00', '2026-08-12 18:50:53.030217+00', NULL),
