	('09e66f4a-289e-4618-b716-4ab057a5521f', '971bd9a8-2a95-44b8-b870-b862309e8417', NULL, 'Mouse flicker all crazy and doesn''t like dragging and dropping.', '<p></p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-11 18:59:08.399+00', '2026-08-24 22:15:50.646265+00', NULL),
	('babaae85-35bc-426f-904a-c0d3d3e6f387', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Add Line Items to Work Tracker in driver app', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-21 13:22:33.35+00', '2026-08-24 15:14:36.082479+00', NULL),
	('2b8ec8fb-aba7-4314-8f82-d63bc12b2999', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Show drivers their price per kilometer in the app', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-21 13:23:54.787+00', '2026-08-24 15:14:40.798694+00', NULL),
	('905c4325-51f7-4c3e-90e8-e35a187ba187', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Assign Contact to WorkTracker', '<ul><li><p>Should be able to pull from previous event and next event for pickup and dropoff contact (like addresses).</p></li><li><p>When contacts are assigned to a work tracker the driver app should allow the driver to see the Contact First and Last Name and phone number and then allow the Driver to "Click to Call" the phone number.</p></li><li><p>This means that the Contact Creation Modal in the Events Page will need to enforce phone number structure (it needs to be a correct phone number).</p></li><li><p></p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-24 14:37:57.874+00', '2026-08-25 10:37:14.195973+00', NULL),
	('ae87f29a-c0b6-4776-8c9f-026b9df49bb7', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Show loading screen when preparing photos on mobile app?', '<p>When you''re creating a new damage report as a driver in the mobile app, AND you select like 30 photos then it takes a while to show the photos on the screen for the driver. this should have some kind of a loading indicator so the driver isn''t all like "What''s going on here? Where are my photos?"</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-20 19:00:07.112+00', '2026-08-25 11:56:40.187164+00', NULL),
	('d3f76a4e-e3e5-4671-9e2d-781fa44d2be4', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Work Tracker Page Driver Filtering', '<p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.loom.com/share/81fee951e6d142b693a5a97d06327afd">https://www.loom.com/share/81fee951e6d142b693a5a97d06327afd</a><br><br>It should probably use the same code as the work tracker modal. If you''re adding a driver to the work tracker and you click on the drop down to select a driver. It only shows you the drivers that are in your zones. I think this page should probably reuse this logic so that we don''t forget about this change in the future.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-24 15:22:24.016+00', '2026-08-25 15:42:12.685065+00', NULL),
	('40a22de3-140e-44e9-969c-11f2ae83e131', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Solution to bleacher selection problem', '<ul><li><p>Solution to bleacher selection problem - Drivers want to select another bleacher but account manager don’t want them to select another bleacher because it changes things a lot.</p><ul><li><p>Add a field to the work tracker for the “driver selected bleacher” and if the driver selects a different bleacher then notify AM and display it on the WorkTrackerModal.tsx</p></li><li><p>How does this affect inspections? Should it change the selected bleacher for the inspection?</p></li><li><p>Think about edge cases. Don’t break anything it’s going into prod today!</p></li></ul></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-25 15:15:25.425+00', '2026-08-25 20:05:25.439442+00', NULL),
	('cda190b9-8779-4a01-874e-38fa1b0c6b07', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Hide distant subrentals.', '<p>When a subrental is further than 2 weeks away (before and after) from the horizontal scroll position.</p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-27 15:37:24.96+00', NULL, NULL),
	('f89987ff-701e-4546-b415-2c2149f817bd', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Documents Expiring Error', '<ul><li><p>Documents Expiring Error - should be clearer how to resolve this error. A driver was confused a while ago. Maybe the account manager should get an error too.</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-25 20:08:59.766+00', '2026-08-26 12:06:19.292031+00', NULL),
	('0ee25a85-273e-4334-8205-bc3628362bf8', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Drivers submit backlog tickets', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-25 20:09:44.632+00', '2026-08-26 13:24:21.033291+00', NULL),
	('4294fde3-c8ac-43ba-8906-5b48c71bb230', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Remove bottom line barrier from damage report page', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-26 13:25:32.258+00', '2026-08-26 18:33:36.074322+00', NULL),
	('f75708eb-e44d-4b12-ab4f-d641b2c35ef4', NULL, NULL, 'work tracker creation', '<p>account managers need to be able to make and edit work trackers on any blaecher</p>', 'completed', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-08-26 19:22:10.523+00', '2026-09-04 22:32:57.200473+00', NULL),
	('b90aa1c0-00fd-4601-a93c-9d822ec12303', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'satisfaction improvements', '<p>Show score by week with a period the same as the sales scorecard (i think monday is the first day of week)<br>drop down should only filter 6 &amp; below or all. If 6 &amp; below force driver to type why.<br>Show rating as fraction (i.e. 9/10 or 2/10) (always /10)</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-27 19:59:51.601+00', '2026-08-28 11:53:33.391618+00', NULL),
	('bbdd70dd-10d9-43b5-aa57-4c227241efd1', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Bug Cannot create work trackers on subrentals', '<p>If you''re an Account Manager and you create a subrental, you can create events on it but you cannot create work trackers on it.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-27 15:33:11.914+00', '2026-08-27 17:43:46.741636+00', NULL),
	('1a78ec4d-943b-48c3-b66c-0eb76ca935d2', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Driver Satisfaction Score', '<ul><li><p>Prompt Driver to answer once per month. Force the driver to answer. They need to give an answer to close the prompt.</p></li><li><p>The question should be "Overall, how satisfied are you with the mobile app?"<br>Options are 1-10. If 6 or less the driver needs to type a reason why in text box.</p></li><li><p>create a page in the web app to see the scores.</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-25 20:16:21.813+00', '2026-08-27 19:07:46.921447+00', NULL),
	('abd0823c-7030-41dc-937e-a0431af5e0e3', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, '(manageTeam): preview and date driver documents', '<p>Add document validity period field to the edit page for drivers.</p><p>Add photo previews</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-28 18:28:00.283+00', '2026-08-28 18:28:01.010159+00', NULL),
	('a78cda97-56e3-4e9c-89a2-707b43902e33', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', NULL, 'Roadmap: create records instantly and autosave edits', '<p>Insert the row in DB on click "New task"<br>Add soft delete for features<br>If "New Task" is fully empty, it should be deleted automatically <br>System messages should be inserted once per session, not for each update<br></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-28 18:33:07.745+00', '2026-08-28 18:33:08.502523+00', NULL),
	('4f9fcd71-2d04-49f4-bf70-26ce26e88e04', NULL, NULL, 'duplicate sub rental in dashboard.', '<p>When i filter in muplitple zones where sub retnals are used it shows that asset twcie in the list. we can solve this by removing the subrented line when duplicates are shown or but a filter that removes all sub rented units from the list. or ideally both.</p>', 'to_do', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-08-24 17:13:53.03+00', NULL, NULL),
	('5d25d3b4-7e73-492a-99a2-91b6d48ef6f3', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Record Payment Not Working', '<p>When accounting clicks on record payment. Should be able to handle negative values.<br>Payment Types:</p><ul><li><p>Manual Credit Card</p></li><li><p>ACH Payment</p></li><li><p>Check</p></li><li><p>Stripe (should be populated via stripe webhook pretty sure it’s this: src/app/api/stripe/webhook)</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-31 17:25:38.723+00', '2026-09-03 22:18:53.121717+00', NULL),
	('fbd83b8c-0bc3-4eba-9418-1f17e94b923d', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Canadian Quotes Issues', '<p>Just no taxes in the CAD office, and not error pops up saying quote saved but email failed to send</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-31 18:39:47.27+00', '2026-09-03 19:48:15.759797+00', NULL),
	('856c8daf-9ad9-4986-bc5a-35a62b3c2d46', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'billing info on invoice', '<p>add a space for billing info if different from event info</p>', 'to_do', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-08-27 13:30:53.165+00', NULL, NULL),
	('a19a53f8-2f29-4d91-88cc-9323a55b36fc', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Amount on Quotes & Bookings Page', '<p>Right now this is just the value that was entered on dashboard but should also include the sum of line items.</p><ul><li><p>Subtotal</p></li><li><p>Tax</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-31 17:25:50.769+00', '2026-09-01 14:58:17.118331+00', NULL),
	('98c545dd-c3e8-4336-b983-c62db9883641', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'QBO Status', '<p>Add a status for the accountants to mark the quote as in qbo = true. It will be false by default. Should be filterable by this status.<br></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-08-31 17:25:08.917+00', '2026-09-01 15:39:04.587245+00', NULL),
	('b4927de6-af68-4180-9cba-d62cef8db516', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'when client paid for quote it ask to resign it', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-09-03 14:04:10.777+00', '2026-09-03 18:31:11.320887+00', NULL),
	('9c952cd5-bdba-4cfe-9aca-d7e30226fc0d', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Driver App - Abandon Trip', '<p>Drivers should be able to abandon a trip to get it out of their to-do list and should notify the account manager to delete or reschedule the work tracker. Should also have a similar work flow to decline trips.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:29:09.03+00', '2026-09-14 13:35:24.140676+00', NULL),
	('398ffd2c-52c1-47c4-a67f-669328c72c1d', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Disclaimer on Quote change', '<p>Standard delivery &amp; setup window is 1-3 days before the event starts, pickup 1-3 days after the event ends.<br><br>Overdue payments are charged at 2% interest per month.</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:40:35.517+00', NULL, NULL),
	('95bb918f-543f-434b-b4a6-a1ce8c2474a3', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Zeeno found another bug', '<p>Another bug I tracked from a quote I sent to the client is the following:<br><br>On our software/platform, it showed under the log that I sent the quote and to what email. The client responded, in which I got a direct response in my Gmail, however; it did not show that the customer opened the email/quote under ''Customer Activity" in the quote log. Not sure if that is due to privacy/firewall settings on their end, but I wanted to bring it to your attention just incase <a target="_blank" rel="noopener noreferrer" href="https://bleacherrentals.slack.com/team/U0A5E6MANUF"><strong>@Josh Redgrift</strong></a>.</p>', 'to_do', 0, true, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-09 20:26:17.242+00', NULL, NULL),
	('65ed7d39-87d4-4b97-ac07-3775c2e36118', '9c22d49d-dbb9-4b24-9175-666edd58b4c2', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'POC Phone number link', '<p>Drivers would like to be able to press on the point of contact phone number and have it pop up to call, similar to how the address works with maps.</p>', 'completed', 0, true, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '04d8fe31-ba63-4037-8f89-c6383bdcfade', '2026-09-02 16:30:20.703+00', '2026-09-04 19:35:18.763244+00', NULL),
	('dab90566-f097-420a-8cea-507abe3eb539', NULL, NULL, 'Dashboard search', '<p>Would love a search feature on the dashboard! (Ctrl F doesn''t work) ... just to look for events etc. easier. :)</p><p>Krista</p>', 'to_do', 0, true, NULL, '23b6f483-dd76-4add-baa5-4d07fed608a8', '2026-09-01 19:37:33.093+00', NULL, NULL),
	('09637ad8-9dd8-4d61-845f-9771c9a431bf', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Driver Tax Allow Decimals', '<p>Qebec has 14.975% tax so we could change this to an int collumn and specify a max of 3 decimal points and then keep it an int or we can create some kind of decimal supporting column in supabase and then interprete it with powersync text type.<br><br>Either way make sure you create a column and deprecrate the old one. keep a trigger to keep them in sync and then when no other mobile apps are running any versions that look at the old column we can drop it then. but should keep in sync in the mean time.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-04 14:00:46.037+00', '2026-09-04 20:10:16.062955+00', NULL),
	('b6184ffb-5957-4109-abc8-2eaf07ca8a4e', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Cleanup alerts', '<p>Don''t need the "Work Tracker Still in Draft Alert" anymore.</p><p>also i think theres a bunch of issues with alerts not saving properly</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:50:44.851+00', NULL, NULL),
	('bf60cb1a-b022-4316-a205-14d44348cf3f', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Filter Worktrackers by CAD/USD', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-04 14:04:24.109+00', '2026-09-04 20:10:20.792739+00', NULL),
	('86fd3150-83ea-4c5b-a464-9d9ecfaa5e2d', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Quantities in WT Line items should support one decimal point.', '<p>qty_decimal int with note saying interpreted as one decimal point so 10 = 1 14 = 1.4</p><p>or you can just. go with a full actual decimal point column</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-04 14:06:08.098+00', '2026-09-04 20:10:39.969388+00', NULL),
	('f206c8fc-215a-471a-a7dc-93bb4be81a42', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Subrental Hide by scroll position', '<p>• ⁃ Don’t show subrentals more than two weeks out should add and remove rows based on horizontal scroll position. Don''t know if this is needed for the end of quarter but definitely needed eventually.</p><p></p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:48:03.868+00', NULL, NULL),
	('ba120fc7-c20c-49cb-8f83-98780c4aee61', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'WorkTracker Page add Stats', '<ul><li><p>Each line in worktracker page should have</p><ul><li><p>Drive Time</p></li></ul></li></ul><p>• ⁃ Milage / kms<br><br>With totals</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:43:36.199+00', '2026-09-10 12:44:02.411893+00', NULL),
	('bb0d333b-d07a-45b0-bd27-237ac248a323', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Disclaimer Automatic', '<ul><li><p>Automatically create client facing note when creating new quote</p></li></ul><p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:43:08.917+00', '2026-09-10 12:43:26.845045+00', NULL),
	('e7b5e315-51ad-4f86-af35-295d3c370e81', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Improve Contact Selection for Quotes and WorkTrackers', '<p>should be able to see the contact information like phone number on the work tracker if possible. should also be able to edit the contact right then and there without leaving to the contacts and companies page.</p>', 'in_progress', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:45:51.1+00', NULL, NULL),
	('43edb23f-9fb9-4bc6-b84a-c2c4848640aa', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Web App - WT Change Bleacher Request', '<p>When a driver selects a new bleacher in the web app it should notify everyone on that zone by putting an alert on the WorkTrackers page and letting the account manager dive in to change it.</p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:26:42.113+00', NULL, NULL),
	('2105e6c6-fd38-4f4f-a36f-87d77f554f72', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Better WorkTracker Time Selections', '<p>Any time exact or flexible time entry</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:44:20.049+00', '2026-09-10 12:45:22.83755+00', NULL),
	('8f98bb31-b4fb-4aea-ad65-e1ff1bfdb674', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Secondary Sort WorkTracker Page', '<p>Order by pickup time on work tracker page make time exact for now input time field.</p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:45:23.765+00', '2026-09-10 12:45:36.586394+00', NULL),
	('773e4b4c-6037-4e5d-9eb9-d0d0314ae093', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Add currency sign for quotes', '<p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '2026-09-02 17:53:50.315+00', '2026-09-03 18:31:05.326657+00', NULL),
	('8dfc21f2-f986-49b6-b00d-ef70bf49d740', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Update Addresses', '<p><strong>Follow this format for all addresses</strong></p><p>Street name</p><p>City, State/prov</p><p>Postal/zip</p><p></p><p>referring to anything customer facing. mostly on PDF and quote</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:39:36.985+00', NULL, NULL),
	('b91e1e73-7ed1-4ecc-90dc-97bb403cbc31', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Ability to save filter sorting', '<p>Having to reenter filters on the quotes and bookings page every time you leave the page, and even when duplicating the tab.<br><br>If you could have a way to create a preset that automatically saves the filters you have applied so when you leave the page and come back nothing changes. Or a way to open something in a new tab instead.</p>', 'completed', 0, true, '9bddb34c-d84e-4d11-852a-27f16de08379', '788a4690-2a6f-4ad7-9365-3669d230aee0', '2026-09-04 15:21:12.639+00', '2026-09-04 19:34:50.67881+00', NULL),
	('6e6a9960-0f68-417c-b451-b33d8affe379', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'damage reports and mark as “Fixed”', '<p>Drivers need to create damage reports and mark as “Fixed” to preserve repair history. This will show the Damage Report with a Fixed indicator somehow probably seating and hauling can be marked as none, minor, major, fixed.<br>fixed should not require a maintenance event to mark as resolved on the web app.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-04 14:28:12.881+00', '2026-09-09 15:56:53.808974+00', NULL),
	('9196a241-5bf0-4cc9-a9dc-7542e7d2ae74', '971bd9a8-2a95-44b8-b870-b862309e8417', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Documents expiring Error', '<p>Jake Lowen couldn''t accept a trip and didn''t know why it turns out the trip was on a date that was after his documents will expire so he needed to update with documents before taking the trip and the error code wasn''t clear enough. it might have need text too small and maybe it should take them to the document it doesn''t like.</p>', 'completed', 0, true, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-08-20 13:47:22.971+00', '2026-09-04 19:38:19.887895+00', NULL),
	('009c1a90-8d11-419f-8eb5-f52a46a31ad0', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'remove still in draft alert', '<p>mike texted me to make this ticket</p>', 'to_do', 0, true, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-08 21:36:53.253+00', NULL, NULL),
	('ad0e4c94-c536-4857-b175-b16dfacba49a', NULL, NULL, 'Phone numbers are like the address', 'Hey guys, it would be great if we could get the phone numbers set up like address’ where we tap and it opens a prompt to call or text the number.', 'to_do', 0, true, NULL, '76a29929-71ce-478c-a03e-772b110bddb0', '2026-09-07 14:41:41.201+00', NULL, '2026-09-07 14:46:52.378+00'),
	('1128fd5e-9aaf-4a2d-90f8-ea43ecf0c4ec', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Driver App - Work Tracker Type', '<p>• ⁃ Display the actual work trackers as each type properly. Repairs and site visits don’t require pickup and drop</p><ul><li><p>Bill of Lading</p></li><li><p>Trip History</p></li></ul><p></p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:21:31.898+00', '2026-09-11 12:58:28.964511+00', NULL),
	('cfb8cc5d-0c84-4835-bf0d-7fcfd1c43601', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Hide all Subrentals button', '<p>• ⁃ Toggle to hide all sub rentals</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:49:20.285+00', NULL, NULL),
	('fb49959c-d7af-4e8e-b325-a1d6d140c4b0', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Paginate Quotes and Bookings Page', '<p>its getting out of hand</p><p>keep in mind the filter logic is used for the sales scorecard too. make sure you don''t mess with any numbers here.</p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:33:46.65+00', NULL, NULL),
	('62d1350a-661b-4de9-86f5-75440ddf3445', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Annual Inspection Dates & Notifications', '<p><strong>Josh:</strong><br>Each asset should have an inspection due date. Find some way to flag this. A warning for a month out and then a alert or something for a over due inspection.</p><p>New document for Inspection PDF should be updated.<br><br><strong>Michelle: </strong><br>Is it possible to get another field added in under the assets to keep track of their annual inspection dates. I had this on my damage spreadsheets and now that we arent using these for damage reporting I need to get this info into the software to keep track of. End goal would be to have this notify us when getting close to inspection date, but for now just having a field so I can manually put those in and keep them up to date would be extremely helpful.</p><p></p>', 'completed', 0, true, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-07-27 19:38:26.125+00', '2026-09-09 13:33:46.471288+00', NULL),
	('eddcb51e-59d7-4b85-8207-cbe2b5132eb5', NULL, NULL, 'test', '<p>testtdzdsiunfkajsnDSFK</p>', 'to_do', 0, true, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-08 14:01:52.918+00', NULL, '2026-09-10 12:55:37.55+00'),
	('3b7f735c-b0fd-405f-8497-7d1fbde011b1', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Driver App - New Pickup / Drop Off Time Value', '<p>• ⁃ Support a new time type that’s not just a string value - deprecate old time type</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:23:20.715+00', '2026-09-14 13:35:14.763774+00', NULL),
	('a99e308d-adcd-42f1-8ee9-ba083910282a', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Driver App - Bill Of Lading', '<p></p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:22:01.899+00', NULL, '2026-09-10 12:22:25.882+00'),
	('e94e08e1-7bd3-44b2-8375-83c29d419a2e', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Driver App - New Address Formatting', '<p>Addresses are saved properly so they should be handled to support the old type and the new address so drivers can see all relevent info</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:24:56.116+00', '2026-09-14 13:35:20.932324+00', NULL),
	('28043c3f-0767-408e-bb1b-feac31141b1c', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', 'c42cf160-f426-4eb0-a150-9665ba679edf', 'Driver App - Annual Bleacher Inspections', '<p>Drivers need to be able to access the inspection documents and all that junk on each bleacher.</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:25:59.914+00', NULL, '2026-09-14 13:42:43.811+00'),
	('a7fa6bda-b4d0-447a-8feb-443c90f72011', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'Drivers need to stop creating duplicate damage reports', '<p>Create a "Select All that Apply" feature when a driver enters a damage report. First find all the open damage reports for this bleacher and then get the driver to select all that still apply. If some of them don''t apply then maybe the driver could request to have the damage report closed? IDK if this is a good idea or not. I''m just thinking that psychologically it will help the driver to feel like they are reporting damage when they see it and not creating duplicate damage reports.<br><br>Maybe drivers should just see all open damage reports by default.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-04 14:22:22.404+00', '2026-09-10 14:50:15.143252+00', NULL),
	('8923caae-c372-40d0-9c12-1fcbc18ca3a4', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Lost with Reason', '<p><strong>Lost Reasons</strong></p><ul><li><p>Out of service area (this is for actually out of our coverage area)</p></li><li><p>Sold out</p></li><li><p>Size doesn’t work (indoor)</p></li><li><p>Price too high</p></li></ul><p>• ⁃ Other with note</p><p></p><p></p><p>when you mark a quote as lost it should require one of these answers before saving</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:36:14.134+00', '2026-09-14 13:35:29.013097+00', NULL),
	('52659693-9e87-4cb2-9f60-74e40eca66c1', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Dashboard Damage Strips', '<p>Should start on First Damage report created at date and then end on maintenance event start date if exists.</p>', 'completed', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 13:49:31.926+00', '2026-09-14 13:35:32.198434+00', NULL),
	('ec12737c-5d0c-44cc-9345-74f31d9c3560', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'WT allow negative values in custome line item', '<p></p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-11 13:10:09.614+00', NULL, NULL),
	('40a4d27c-100f-4c9f-af01-02433acf4764', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, '', '<p></p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-11 15:06:05.844+00', NULL, '2026-09-14 13:36:36.039+00'),
	('2f49222c-5537-4af7-a2b2-c40660ee8640', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Drivers to See All Assets', '<p>Drivers should be able to see the whole asset list without editing.</p>', 'to_do', 0, false, '43f82f56-f6e2-4400-aeb2-7c5195c557ad', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-11 15:06:06.059+00', NULL, NULL),
	('03b2e1e7-18a7-4f0c-b3f6-7e14d3dab5a1', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Contact & Venue History', '<p>In good shuffle you can click on a contact or a venue to view the other events that this contact or venue had. You can also set a default venue for each contact which is cool.</p>', 'in_progress', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:30:50.115+00', NULL, NULL),
	('a534d7ba-f982-46d6-9b54-0a6093c56b60', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Reach out To Driver Having an Issue with Mobile app', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:57:01.082+00', '2026-09-14 15:29:44.4196+00', NULL),
	('bbbe9a42-d598-4f73-9ba5-c4b31ab0cc58', 'a3dad991-87b2-4219-9ea4-f2ab1fbcdd6e', NULL, 'submit 1.9.0 to app stores', '<p></p>', 'completed', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-11 12:07:12.48+00', '2026-09-11 12:07:32.653785+00', NULL),
	('4b999e00-898b-4c7d-b646-044b54f4f6ff', NULL, NULL, 'Bug fix with manual payments,', '<p>When i go to billing in a quote, for NC , Gastonia, I sent an original quote for $61,000, then uptated it to be $29,000, the old amount shows up in (what bill do you want to apply this to. also, cc, the account manager in the email sent. and let us preview the emails before senting, similar to quickbooks invoicing.     </p>', 'to_do', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-09-12 20:03:57.73+00', NULL, '2026-09-12 20:09:26.371+00'),
	('a645b395-4b9f-4e92-acb5-3397c28601b1', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Cheryl Rivera - TX - Fort Worth - Homecoming - issue', '<p>Zeeno&nbsp;&nbsp;[1:27 PM]<br></p><p>Hey <a target="_blank" rel="noopener noreferrer" href="https://bleacherrentals.slack.com/team/U0A5E6MANUF"><strong>@Josh Redgrift</strong></a>,<br><br>This is a quote that was sent to a client and the log confirms it, but still shows as ''Draft'' in the status when I look at quotes section</p><p>2 files&nbsp;</p><p>Zeeno&nbsp;&nbsp;[1:36 PM]<br></p><p>Sent <a target="_blank" rel="noopener noreferrer" href="https://bleacherrentals.slack.com/team/U05HWBFU0VB"><strong>@Krista Timmermans</strong></a> a new test one just now, and it is showing the status as quoted. So it seems to be working sometimes</p><p>Krista Timmermans&nbsp;&nbsp;[2:30 PM]<br></p><p>I just signed the test one - is that showing in your logs <a target="_blank" rel="noopener noreferrer" href="https://bleacherrentals.slack.com/team/U08QWLPPG4W"><strong>@Zeeno</strong></a>?</p><p>Zeeno&nbsp;&nbsp;[6:09 PM]<br></p><p>IMG_20260908_180838.jpg&nbsp;</p><p>[6:09 PM]</p><p>IMG_20260908_180904.jpg&nbsp;</p><p>[6:09 PM]</p><p>I would show signed qupte under Customer Activity as well</p><p>Josh Redgrift&nbsp;&nbsp;[9:41 AM]<br></p><p>hmmm I''ll take a look at what''s going on with this one later today.<br></p><h2><br>SEPTEMBER 11</h2><p></p><p><br><a target="_blank" rel="noopener noreferrer" href="https://bleacherrentals.slack.com/team/U0A5E6MANUF"><strong>@Josh Redgrift</strong></a>, I did find a work around solution to our ''draft'' status vs ''quoted'' when the quote is actually sent. I went to the scheduler, and when I click on the event, I notice the status is not changed to quoted, so I just manually do that for the ones that are not anchoring to the scheduler. I wanted to share this, incase this helps you with investigating the root cause of the issue, so that you dont have to spend excessive time investigating</p><p>[2:49 PM]</p><p>And yes, once I change the status to quoted on the scheduler, it will show the official status as ''quoted''</p><p></p>', 'to_do', 0, true, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-09 13:42:10.069+00', NULL, NULL),
	('e37ff258-3a66-4e76-a1c0-1b5c864a4646', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', 'cf0187d0-d9e5-4c62-8696-f3220c435b4d', 'Video on how to use Internal Messaging', '<p>no ones using it right now because they can''t seem to figure it out lol</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:35:07.9+00', NULL, NULL),
	('cc104145-57b1-4c62-91e1-260369980f8d', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', '90e4e2a3-a387-4321-9b26-29b46175fdc1', 'Rename details to Quote', '<p>on the current event panel the Details button that brings you to the Quote should be renamed to Quote</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-10 12:38:06.818+00', NULL, NULL),
	('a1ccb494-7ba0-4704-9163-891d5cf96c64', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Driver App - Support Passwordless Auth', '<p>This means the first screen is an email input field and two buttons to log in with google or apple. the the user submits their email if they have a password, prompt to enter the password else prompt the user to click the link in their email.</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-14 15:33:00.793+00', NULL, NULL),
	('ed942ce8-3858-4769-95c8-fe9bb552a8e9', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Driver App - You Cannot Create Account Here', '<p>The driver app login screen should say that the driver must receive an email from an account manager to create an account there. Once you''ve created an account there, log in here with the same credentials. You must use the same email that the invitation was sent to.</p>', 'to_do', 0, false, NULL, '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-14 15:29:45.606+00', NULL, NULL),
	('3bc5ea03-ed93-43a0-90fd-ae998071ad95', NULL, NULL, 'creating quotes and assigning bleachers', '<p>When assigning bleachers to a quote , I clikc go to dashboard,  this goes to todays date,  can we have this go to the quoted date so we can see whats available better, and potencial auto assign the best bleacher</p>', 'to_do', 0, true, NULL, '6b080032-c889-4ce5-86e0-5a564a4d97f7', '2026-09-12 13:55:25.648+00', NULL, NULL),
	('899a6dc3-9fb2-40fe-b335-41bb8b9df7c1', '71d6e0b4-ffaa-42c5-9e58-5928044b24e3', NULL, 'Help Kaitlyn with QBO Error', '<p></p>', 'to_do', 0, false, '9bddb34c-d84e-4d11-852a-27f16de08379', '9bddb34c-d84e-4d11-852a-27f16de08379', '2026-09-14 15:34:27.044+00', NULL, NULL);


