-- ─────────────────────────────────────────────────────────────────────────────
-- Alert cleanup migrations, repeated here because seed data is loaded AFTER the
-- migrations run on `npx supabase db reset` — without this the seeded alerts
-- would bypass them. Keep in sync with the migration files named below.
-- ─────────────────────────────────────────────────────────────────────────────

-- supabase/migrations/20260918130000_delete_legacy_row_count_alerts.sql
-- The "Event Requirements Not Met" alert no longer compares the legacy 7/10/15-row counts on
-- Events (requirements now come from bleacher-type line items). Delete the stored alerts the old
-- rule produced, e.g. "Bleacher mismatch — 15-row: 0 needed, 2 assigned.", so they stop showing
-- for events nobody re-opens.
--
-- The match is case-sensitive on purpose: legacy messages read "15-row: 2 needed", while current
-- messages use the bleacher type's name ("15-Row, 450 Seat: 2 needed"), so they never match.
-- UserAlerts has no ON DELETE CASCADE, so its rows go first.

WITH legacy AS (
  SELECT id
  FROM public."Alerts"
  WHERE title = 'Event Requirements Not Met'
    AND message ~ '(^|, |— )(7|10|15)-row: \d+ needed, \d+ assigned'
)
DELETE FROM public."UserAlerts"
WHERE alert_uuid IN (SELECT id FROM legacy);

DELETE FROM public."Alerts"
WHERE title = 'Event Requirements Not Met'
  AND message ~ '(^|, |— )(7|10|15)-row: \d+ needed, \d+ assigned';

-- supabase/migrations/20260921123000_delete_stale_scheduling_conflicts.sql
-- One-off: delete "Scheduling Conflict" alerts that no longer describe a real double booking.
--
-- An alert is only rewritten when something saves the entity it hangs off, and until now the
-- ripple that follows a save read the event's bleachers AFTER the save. Taking a bleacher off an
-- event therefore left its neighbours holding a conflict with an event that had given the bleacher
-- up, with nothing to ever re-check them. The ripple is fixed (it now carries the removed
-- bleachers, and bounds on event_end so events under way are included), but the alerts it already
-- stranded have to be cleared once.
--
-- The predicate mirrors schedulingConflict.evaluate: the owning event must be booked and not
-- deleted, and some OTHER bleacher event on the same bleacher — also booked and not deleted — must
-- overlap it. The occupied window runs setup_start (or event_start) to teardown_end (or
-- event_end), and touching at the boundary counts as an overlap, exactly as the inclusive
-- comparison in the definition does.
--
-- UserAlerts has no ON DELETE CASCADE, so its rows go in the same statement's first CTE.

WITH stale AS (
  SELECT a.id
  FROM public."Alerts" a
  JOIN public."BleacherEvents" be ON be.id = a.entity_uuid
  JOIN public."Events" e ON e.id = be.event_uuid
  WHERE a.title = 'Scheduling Conflict'
    AND NOT EXISTS (
      SELECT 1
      FROM public."BleacherEvents" be2
      JOIN public."Events" e2 ON e2.id = be2.event_uuid
      WHERE be2.bleacher_uuid = be.bleacher_uuid
        AND be2.id <> be.id
        AND e2.event_status = 'booked'
        AND NOT coalesce(e2.deleted, false)
        AND NOT coalesce(e.deleted, false)
        AND e.event_status = 'booked'
        AND coalesce(e2.setup_start, e2.event_start)
              <= coalesce(e.teardown_end, e.event_end)
        AND coalesce(e2.teardown_end, e2.event_end)
              >= coalesce(e.setup_start, e.event_start)
    )
),
deleted_user_alerts AS (
  DELETE FROM public."UserAlerts" ua
  WHERE ua.alert_uuid IN (SELECT id FROM stale)
)
DELETE FROM public."Alerts" a
WHERE a.id IN (SELECT id FROM stale);

-- supabase/migrations/20260918140000_delete_past_alerts.sql
-- No alerts in the past — see docs/specs/no-past-alerts.md.
--
-- delete_past_alerts() removes every alert whose entity is over, plus alerts whose entity no longer
-- exists (or whose event is soft-deleted), together with their UserAlerts. "Today" is Toronto's
-- date. An event is past after its end date; a bleacher event goes with its event; a work tracker
-- is past after its date. A missing date is never treated as past.
--
-- It replaces the row-by-row loop in /api/cron/alerts, which read at most 1,000 alerts per run
-- (PostgREST max_rows) and issued one query per alert. The Vercel cron now calls this through rpc.
--
-- One statement: UserAlerts and Alerts are deleted by data-modifying CTEs over the same snapshot.
-- UserAlerts_alert_uuid_fkey is NO ACTION, which Postgres checks at the end of the statement, so the
-- order is safe.

CREATE OR REPLACE FUNCTION public.delete_past_alerts()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  today date := (now() AT TIME ZONE 'America/Toronto')::date;
  deleted_count integer;
BEGIN
  WITH stale AS (
    SELECT a.id
    FROM public."Alerts" a
    WHERE
      (a.entity_type = 'event' AND NOT EXISTS (
        SELECT 1 FROM public."Events" e
        WHERE e.id = a.entity_uuid
          AND NOT coalesce(e.deleted, false)
          AND (e.event_end IS NULL OR e.event_end >= today)
      ))
      OR (a.entity_type = 'bleacher_event' AND NOT EXISTS (
        SELECT 1 FROM public."BleacherEvents" be
        JOIN public."Events" e ON e.id = be.event_uuid
        WHERE be.id = a.entity_uuid
          AND NOT coalesce(e.deleted, false)
          AND (e.event_end IS NULL OR e.event_end >= today)
      ))
      OR (a.entity_type = 'work_tracker' AND NOT EXISTS (
        SELECT 1 FROM public."WorkTrackers" w
        WHERE w.id = a.entity_uuid
          AND (w.date IS NULL OR w.date >= today)
      ))
  ),
  deleted_user_alerts AS (
    DELETE FROM public."UserAlerts" ua
    WHERE ua.alert_uuid IN (SELECT id FROM stale)
  ),
  deleted_alerts AS (
    DELETE FROM public."Alerts" a
    WHERE a.id IN (SELECT id FROM stale)
    RETURNING 1
  )
  SELECT count(*) INTO deleted_count FROM deleted_alerts;

  RETURN deleted_count;
END;
$$;

-- Only the server (the cron's service-role client) may run it.
REVOKE ALL ON FUNCTION public.delete_past_alerts() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.delete_past_alerts() TO service_role;

-- One-off cleanup of everything already past.
SELECT public.delete_past_alerts();


-- Percentage payment schedules: backfill copied from
-- 20260922120000_percentage_payment_schedules.sql. The seed runs after the migrations, so it
-- recomputes percentage_bps from the seeded amount_cents the same way the migration does.
-- Existing hashes still read amount_cents while this backfill runs.
WITH source AS (
  SELECT pi.*, public.payment_schedule_total_cents(event_uuid) AS total,
    sum(amount_cents) OVER (PARTITION BY event_uuid) AS scheduled,
    count(*) OVER (PARTITION BY event_uuid) AS n,
    row_number() OVER (PARTITION BY event_uuid ORDER BY due_date, id) AS position
  FROM public."PaymentInstallments" pi
), shares AS (
  SELECT *, CASE WHEN total = 0 THEN floor(10000.0 / n)
    ELSE amount_cents::numeric * 10000 / total END AS exact FROM source
), ranked AS (
  SELECT *, row_number() OVER (PARTITION BY event_uuid ORDER BY exact - floor(exact) DESC, due_date, id) AS rank,
    sum(floor(exact)) OVER (PARTITION BY event_uuid) AS floors FROM shares
)
UPDATE public."PaymentInstallments" pi SET percentage_bps =
  CASE WHEN r.total = 0 THEN floor(r.exact) + CASE WHEN r.position = r.n THEN 10000 - r.floors ELSE 0 END
    WHEN r.scheduled = r.total THEN floor(r.exact) + CASE WHEN r.rank <= 10000 - r.floors THEN 1 ELSE 0 END
    ELSE round(r.exact) END
FROM ranked r WHERE r.id = pi.id;

-- Repeats the backfill in 20260921131500_work_tracker_status_changed_at.sql:
-- seed data loads after migrations run, so it found no trackers to fill.
UPDATE public."WorkTrackers"
   SET "status_changed_at" = COALESCE(
         "completed_at", "abandoned_at", "declined_at",
         "started_at", "accepted_at", "released_at", "updated_at"
       )
 WHERE "status_changed_at" IS NULL;


