-- One row per scenario. Offsets are days from the seed day (0 = today). Office decides currency:
-- 'USD' = Bleacher Rentals Florida LLC, 'CAD' = Bleacher Rentals (Ontario), NULL = legacy event.
  "id", "event_name", "event_status", "deleted", "created_at",
  "setup_start", "event_start", "event_end", "teardown_end", "quote_valid_till",
  "lenient", "total_seats", "hsl_hue", "event_type_uuid", "sales_office_uuid", "created_by_user_uuid",
  "contact_uuid", "finance_contact_uuid", "venue_uuid", "address_uuid", "terms_and_conditions_uuid",
  "invoice_number", "po_number", "tax_percent", "tax_amount_cents", "goodshuffle_url", "is_qbo",
  "lost_reason", "internal_notes"
)
SELECT
  ('a7000000-0000-4000-8000-' || lpad(n::text, 12, '0'))::uuid,
  'AR Seed: ' || name,
  status::"public"."event_status",
  deleted,
  (current_date + created) + time '09:30',
  current_date + setup, current_date + start, current_date + finish, current_date + teardown,
  current_date + valid_till,
  false, seats, hue,
  CASE event_type
    WHEN 'rural' THEN '672ef2ed-86f7-483f-b9b9-1bbb3054f53c'
    WHEN 'city' THEN '05b256fe-4df6-412d-bfc3-cc78e037ee99'
    WHEN 'corporate' THEN '3ea1a08f-5ba3-4210-af80-9373d03bcbd0'
  END::uuid,
  CASE office
    WHEN 'USD' THEN '5cfc2897-3990-41cd-b29d-06f5ad8809cc'
    WHEN 'CAD' THEN '0491f29d-2ead-4e1f-9d20-f52c084b344d'
  END::uuid,
  CASE am
    WHEN 'josh' THEN '9bddb34c-d84e-4d11-852a-27f16de08379'
    WHEN 'montana' THEN '31a13a33-985d-40c8-8d8e-7cbe94cb4bc5'
    WHEN 'zeeno' THEN '746927fc-e6c7-4cff-b7a4-a12130a5c3d6'
    WHEN 'krista' THEN '23b6f483-dd76-4add-baa5-4d07fed608a8'
  END::uuid,
  ('7d000000-0000-4000-8000-' || lpad(contact_n::text, 12, '0'))::uuid,
  ('7d000000-0000-4000-8000-' || lpad(finance_n::text, 12, '0'))::uuid,
  ('7e000000-0000-4000-8000-' || lpad(venue_n::text, 12, '0'))::uuid,
  ('7a000000-0000-4000-8000-' || lpad(address_n::text, 12, '0'))::uuid,
  CASE terms
    WHEN 'standard' THEN '805f9267-38ab-4442-84b9-7c9ba3f5f36e'
    WHEN 'french' THEN '2a02b08a-769b-44fa-8a36-9e4006e5eaf5'
  END::uuid,
  invoice, po, tax_percent, tax_cents,
  CASE WHEN goodshuffle THEN 'https://example.com/goodshuffle/ar-seed-' || n END,
  qbo,
  lost_reason::"public"."event_lost_reason",
  'AR seed #' || n || ' — ' || notes
