-- `inst` names the installment a payment was made against (NULL = unapplied, the pool fills
-- oldest-first). Stripe rows look like the webhook's; manual rows carry method, author and
-- reference, as the Record Payment dialog writes them. A failed row has no paid_at and is never
-- counted.
  "id", "event_uuid", "installment_id", "intended_installment_id", "amount_cents", "currency", "status",
  "entry_source", "payment_method_type", "reference", "payer_name", "payer_email", "notes",
  "recorded_by_user_uuid", "paid_at", "created_at",
  "stripe_payment_intent_id", "stripe_checkout_session_id", "stripe_connection_uuid"
)
SELECT
  ('a73000' || lpad(v.ev::text, 2, '0') || '-0000-4000-8000-' || lpad(v.k::text, 12, '0'))::uuid,
  e.id,
  ('a72000' || lpad(v.ev::text, 2, '0') || '-0000-4000-8000-' || lpad(v.inst::text, 12, '0'))::uuid,
  ('a72000' || lpad(v.ev::text, 2, '0') || '-0000-4000-8000-' || lpad(v.inst::text, 12, '0'))::uuid,
  v.amount, v.currency, v.status, v.source,
  CASE WHEN v.source = 'stripe' THEN 'stripe' ELSE v.method END,
  CASE WHEN v.source = 'stripe' THEN v.method ELSE v.reference END,
  ct.first_name || ' ' || ct.last_name,
  ct.email,
  v.notes,
  CASE WHEN v.source = 'manual' THEN e.created_by_user_uuid END,
  CASE WHEN v.status = 'succeeded' THEN (current_date + v.paid) + time '15:20' END,
  (current_date + v.paid) + time '15:20',
  CASE WHEN v.source = 'stripe' THEN 'pi_seed_ar_' || v.ev || '_' || v.k END,
  CASE WHEN v.source = 'stripe' THEN 'cs_seed_ar_' || v.ev || '_' || v.k END,
  CASE WHEN v.source = 'stripe' THEN so.stripe_connection_uuid END
FROM (VALUES
  --ev k  inst  amount    currency status       source    method (stripe: instrument) reference           paid notes
  ( 1, 1,    1,   576300, 'CAD', 'succeeded', 'stripe', 'card',               NULL,                -39, NULL),
  ( 3, 1,    1,   288000, 'USD', 'succeeded', 'stripe', 'us_bank_account',    NULL,                -28, NULL),
  ( 3, 2, NULL,   300000, 'USD', 'succeeded', 'manual', 'check',              'Check #20417',       -5, 'Booster club check toward the final balance'),
  ( 4, 1, NULL,   734288, 'USD', 'succeeded', 'stripe', 'card',               NULL,               -149, NULL),
  ( 4, 2,    2,   734288, 'USD', 'succeeded', 'stripe', 'us_bank_account',    NULL,               -118, NULL),
  ( 5, 1,    1,   399000, 'CAD', 'succeeded', 'stripe', 'card',               NULL,                -34, NULL),
  ( 6, 1,    2,   692825, 'USD', 'succeeded', 'stripe', 'card',               NULL,                -26, NULL),
  ( 7, 1,    1,   256800, 'USD', 'succeeded', 'stripe', 'card',               NULL,                -37, NULL),
  ( 7, 2, NULL,   -50000, 'USD', 'succeeded', 'manual', 'manual_credit_card', 'Terminal refund 4471', -9, 'Goodwill credit — the shade canopy arrived late'),
  ( 8, 1,    1,   448403, 'CAD', 'failed',    'stripe', 'card',               NULL,                -59, NULL),
  ( 8, 2, NULL,   200000, 'CAD', 'succeeded', 'stripe', 'card',               NULL,                -57, NULL),
  ( 9, 1,    1,   300000, 'USD', 'succeeded', 'stripe', 'card',               NULL,                -15, NULL),
  (10, 1, NULL,   100000, 'USD', 'succeeded', 'manual', 'ach',                'ACH trace 0710-4471', -20, NULL),
  (12, 1, NULL,   400000, 'USD', 'succeeded', 'stripe', 'card',               NULL,                -50, NULL),
  (14, 1,    1,   254250, 'CAD', 'succeeded', 'stripe', 'card',               NULL,                -69, NULL),
  (14, 2,    2,   254250, 'CAD', 'succeeded', 'manual', 'check',              'Cheque #883',       -48, NULL),
  (15, 1,    1,   203300, 'USD', 'succeeded', 'stripe', 'card',               NULL,                -24, NULL),
  (15, 2, NULL,    20000, 'USD', 'succeeded', 'manual', 'manual_credit_card', 'Terminal auth 90210', -20, 'Charged twice at the counter — refund pending'),
  (19, 1,    1,  5106150, 'CAD', 'succeeded', 'stripe', 'card',               NULL,               -118, NULL),
  (19, 2, NULL,  6808200, 'CAD', 'succeeded', 'manual', 'ach',                'Wire 55-1023',      -44, 'Second installment by wire'),
  (21, 1,    1,   395900, 'USD', 'succeeded', 'stripe', 'card',               NULL,                -19, NULL),
